NAME = 'SloKJV: Slovenian translation of Holy Bible King James Version (1769)'
BOOK = 'I Kings'

CHAPTERS = {
    1: {
        1: 'Torej kralj David je bil zelo star in zvrhan v letih in pokrivali so ga z oblačili, toda ni se mogel ogreti.',
        2: 'Zato so mu njegovi služabniki rekli: »Naj bo za mojega gospoda kralja poiskana mlada devica in naj ta stoji pred kraljem in naj ga neguje in naj leži v tvojem naročju, da se moj gospod kralj lahko ogreje.«',
        3: 'Tako so po vseh Izraelovih pokrajinah iskali za lepo gospodično in našli Šunémko Abišágo in jo privedli h kralju.',
        4: 'Gospodična je bila zelo lepa, negovala je kralja in mu služila, toda kralj je ni spoznal.',
        5: 'Potem se je Hagítin sin Adoníja povišal, rekoč: »Jaz bom kralj,« in si pripravil bojne vozove, konjenike in petdeset mož, da tečejo pred njim.',
        6: 'Njegov oče pa ga nikoli ni razžalil v tem, da bi rekel: »Čemu si tako storil?« In ta je bil tudi zelo čeden mož in njegova mati ga je rodila za Absalomom.',
        7: 'Ta se je posvetoval s Cerújinim sinom Joábom in z duhovnikom Abjatárjem in sledeč Adoníju sta mu pomagala.',
        8: 'Toda duhovnik Cadók, Jojadájev sin Benajá, prerok Natán, Šimí, Reí in mogočni možje, ki so pripadali Davidu, niso bili z Adoníjem.',
        9: 'Adoníja je pri kamnu Zohélet, ki je pri En Rogelu, zaklal ovce, vole in pitano živino ter poklical vse svoje brate, kraljeve sinove in vse Judove ljudi, kraljeve služabnike,',
        10: 'toda preroka Natána, Benajá, mogočnih mož in svojega brata Salomona ni poklical.',
        11: 'Zato je Natán spregovoril Salomonovi materi Batšébi, rekoč: »Mar nisi slišala, da Hagítin sin Adoníja kraljuje, naš gospod David pa tega ne ve?',
        12: 'Zdaj torej pridi, prosim te, naj ti dam nasvet, da boš lahko rešila svoje lastno življenje in življenje svojega sina Salomona.',
        13: 'Pojdi in vstopi h kralju Davidu ter mu reci: ›Mar nisi ti, moj gospod, oh kralj, prisegel pri svoji pomočnici, rekoč: ›Zagotovo bo tvoj sin Salomon kraljeval za menoj in bo sedel na mojem prestolu? Zakaj potem kraljuje Adoníja?‹‹',
        14: 'Glej, medtem ko boš še tam govorila s kraljem, bom tudi jaz vstopil za teboj in potrdil tvoje besede.«',
        15: 'Batšéba je odšla h kralju v sobo. Kralj pa je bil zelo star in Šunémka Abišága je služila kralju.',
        16: 'Batšéba se je upognila in se globoko priklonila. Kralj je rekel: »Kaj želiš?«',
        17: 'Rekla mu je: »Moj gospod, pri Gospodu, svojem Bogu, si prisegel svoji pomočnici, rekoč: ›Tvoj sin Salomon bo zagotovo kraljeval za menoj in bo sedel na mojem prestolu.‹',
        18: 'Sedaj glej, kraljuje Adoníja in sedaj, moj gospod kralj, ti tega ne veš, [namreč]',
        19: 'zaklal je vole, pitano živino in ovc v obilju ter sklical vse kraljeve sinove, duhovnika Abjatárja in poveljnika vojske Joába, toda tvojega služabnika Salomona ni poklical.',
        20: 'Ti pa, moj gospod, oh kralj, oči celotnega Izraela so na tebi, da bi jim ti povedal, kdo bo sedel na prestolu mojega gospoda kralja za njim.',
        21: 'Sicer se bo zgodilo, ko bo moj gospod kralj zaspal s svojimi očeti, da bova jaz in moj sin Salomon šteta [za] prestopnika.«',
        22: 'Glej, medtem ko je še govorila s kraljem, je vstopil tudi prerok Natán.',
        23: 'Kralju so povedali, rekoč: »Glej, prerok Natán.« Ko je ta vstopil pred kralja, se je pred kraljem upognil s svojim obrazom do tal.',
        24: 'Natán je rekel: »Moj gospod, oh kralj, ali si rekel: ›Adoníja bo kraljeval za menoj in on bo sedel na mojem prestolu?‹',
        25: 'Kajti ta dan je odšel dol in v obilju zaklal vole, rejeno živino in ovce ter sklical vse kraljeve sinove, poveljnike vojske in duhovnika Abjatárja; in glej, jedo in pijejo pred njim ter govorijo: ›Živel kralj Adoníja.‹',
        26: 'Toda mene, celó mene, tvojega služabnika, duhovnika Cadóka, Jojadájevega sina Benajá in tvojega služabnika Salomona ni poklical.',
        27: 'Ali je ta stvar storjena s strani mojega gospoda kralja in je nisi pokazal svojemu služabniku, kdo naj bi sedel na prestolu mojega gospoda kralja za njim?«',
        28: 'Potem je kralj David odgovoril in rekel: »Pokličite mi Batšébo.« Prišla je v kraljevo prisotnost in obstala pred kraljem.',
        29: 'Kralj je prisegel in rekel: » Kakor Gospod živi, ki je mojo dušo odkupil iz vse tesnobe,',
        30: 'celo kakor sem ti prisegel pri Gospodu, Izraelovem Bogu, rekoč: ›Zagotovo bo tvoj sin Salomon kraljeval za menoj in on bo namesto mene sedel na mojem prestolu, celo tako bom zagotovo storil ta dan.‹«',
        31: 'Potem se je Batšéba s svojim obrazom pripognila do zemlje, počastila kralja in rekla: »Naj moj gospod kralj David živi na veke.«',
        32: 'Kralj David je rekel: »Pokliči mi duhovnika Cadóka, preroka Natána in Jojadájevega sina Benajá.« In prišli so pred kralja.',
        33: 'Kralj jim je tudi rekel: »S seboj vzemite služabnike svojega gospoda in naredite, da moj sin Salomon jezdi na moji lastni muli in ga privedite dol do Gihona.',
        34: 'Duhovnik Cadók in prerok Natán naj ga tam mazilita za kralja nad Izraelom in zatrobite s šofarjem ter recite: ›Živel kralj Salomon.‹',
        35: 'Potem boste za njim prišli gor, da bo lahko prišel in sedel na moj prestol, kajti on bo kralj namesto mene. Določil sem ga, da bo vladar nad Izraelom in nad Judom.«',
        36: 'Jojadájev sin Benajá je kralju odgovoril in rekel: »Amen. Tudi Gospod, Bog mojega gospoda kralja, tako pravi.',
        37: 'Kakor je bil Gospod z mojim gospodom kraljem, celo tako naj bo s Salomonom in njegov prestol naj naredi večjega od mojega gospoda, kralja Davida.«',
        38: 'Tako so duhovnik Cadók, prerok Natán in Jojadájev sin Benajá, Keretéjci in Péletovci odšli dol in dali Salomonu, da je jahal na muli kralja Davida in ga privedli h Gihonu.',
        39: 'Duhovnik Cadók je iz šotorskega svetišča vzel rog olja in mazilil Salomona. Zatrobili so na šofar in vse ljudstvo je reklo: »Živel kralj Salomon.«',
        40: 'Vse ljudstvo je prišlo za njim gor in ljudstvo je piskalo s piščalmi in se razveseljevalo z veliko radostjo, tako da se je zemlja od njihovega glasu trgala.',
        41: 'Adoníja in vsi gostje, ki so bili z njim, ko so to slišali, so nehali jesti. Ko je Joáb zaslišal zvok šofarja, je rekel: »Čemu je ta hrup iz mesta, [kot bi bila] vstaja?«',
        42: 'Medtem ko je še govoril, glej, je prišel Jonatan, sin duhovnika Abjatárja in Adoníja mu je rekel: »Vstopi, kajti hraber mož si in prinašaš dobre novice.«',
        43: 'Jonatan je odgovoril in Adoníju rekel: »Resnično, naš gospod, kralj David, je Salomona postavil za kralja.',
        44: 'In kralj je z njim poslal duhovnika Cadóka, preroka Natána, Jojadájevega sina Benajá, Keretéjce in Péletovce in dali so mu, da je jahal na kraljevi muli.',
        45: 'Duhovnik Cadók in prerok Natán sta ga mazilila za kralja pri Gihonu in od tam so prišli gor, veseleč se, tako da je mesto ponovno odzvanjalo. To je hrup, ki ste ga slišali.',
        46: 'In Salomon tudi sedi na prestolu kraljestva.',
        47: 'Še več, kraljevi služabniki so prišli, da blagoslovijo našega gospoda, kralja Davida, rekoč: ›Bog naj Salomonovo ime naredi boljše od tvojega imena in naj njegov prestol naredi večji kakor tvoj prestol.‹ In kralj se je na postelji globoko priklonil.',
        48: 'Tudi tako je kralj rekel: ›Blagoslovljen bodi Gospod, Izraelov Bog, ki je danes dal nekomu sedeti na mojem prestolu in moje oči celo to vidijo.‹«',
        49: 'Vsi gostje, ki so bili z Adoníjem, so bili prestrašeni in vzdignili so se ter odšli, vsak mož svojo pot.',
        50: 'Adoníja pa se je bal zaradi Salomona, se vzdignil, odšel in se oprijel oltarnih rogov.',
        51: 'To je bilo povedano Salomonu, rekoč: »Glej, Adoníja se boji kralja Salomona, kajti glej, oprijel se je oltarnih rogov, rekoč: ›Naj mi ta dan kralj Salomon priseže, da svojega služabnika ne bo usmrtil z mečem.‹«',
        52: 'Salomon je rekel: »Če se bo izkazal vrednega moža, ne bo niti las od njega padel na zemljo, toda če bo v njem najdena zlobnost, bo umrl.«',
        53: 'Tako je kralj Salomon poslal in privedli so ga dol od oltarja. In prišel je ter se priklonil kralju Salomonu in Salomon mu je rekel: »Pojdi k svoji hiši.«',
    },
    2: {
        1: 'Torej Davidovi dnevi so se približali, da naj bi umrl in svojemu sinu Salomonu je naročil, rekoč:',
        2: '»Jaz grem pot vse zemlje. Bodi torej močan in se izkaži moža',
        3: 'in ohrani naročilo Gospoda, svojega Boga, da hodiš po njegovih poteh, da ohranjaš njegove zakone, njegove zapovedi, njegove sodbe in njegova pričevanja, kakor je zapisano v Mojzesovi postavi, da boš lahko uspeval v vsem, kar delaš in kamorkoli se obrneš,',
        4: 'da bo Gospod lahko nadaljeval svojo besedo, ki jo je govoril glede mene, rekoč: ›Če tvoji otroci pazijo na svojo pot, da hodijo pred menoj v resnici, z vsem svojim srcem in z vso svojo dušo, tebi ne bo odrezan,‹ je rekel, ›noben mož na Izraelovem prestolu.‹',
        5: 'Poleg tega tudi veš, kaj mi je storil Cerújin sin Joáb in kaj je storil dvema poveljnikoma Izraelove vojske, Nerovemu sinu Abnêrju in Jeterjevemu sinu Amasáju, ki ju je ubil in vojno kri prelil v miru in vojno kri položil na svoj pas, ki je bil okrog njegovih ledij in na njegove čevlje, ki so bili na njegovih stopalih.',
        6: 'Stori torej glede na svojo modrost in ne dopusti, da bi njegova osivela glava šla v miru dol v podzemlje.',
        7: 'Toda izkazuj prijaznost sinovom Gileádca Barzilája in naj bodo izmed tistih, ki jedo pri tvoji mizi, kajti tako so prišli k meni, ko sem pobegnil zaradi tvojega brata Absaloma.',
        8: 'Glej, s seboj imaš Šimíja, Gerájevega sina, Benjaminovca iz Bahuríma, ki me je preklinjal z bolečim prekletstvom na dan, ko sem odšel v Mahanájim, toda prišel je dol, da me sreča pri Jordanu in prisegel sem mu pri Gospodu, rekoč: ›Ne bom te usmrtil z mečem.‹',
        9: 'Zdaj ga torej ne imej brez krivde, kajti moder človek si in veš, kaj mu moraš storiti, temveč njegovo osivelo glavo s krvjo privedi dol k podzemlju.«',
        10: 'Tako je David zaspal s svojimi očeti in bil pokopan v Davidovem mestu.',
        11: 'Dni, ko je David kraljeval nad Izraelom, je bilo štirideset let. Sedem let je kraljeval v Hebrónu, triintrideset let pa je kraljeval v Jeruzalemu.',
        12: 'Potem se je Salomon usedel na prestol svojega očeta Davida in njegovo kraljestvo je bilo silno utrjeno.',
        13: 'Hagítin sin Adoníja je prišel k Salomonovi materi Batšébi. Rekla je: »Prihajaš miroljubno?« Rekel je: »Miroljubno.«',
        14: 'Poleg tega je rekel: »Nekaj ti imam povedati.« Rekla je: »Povej.«',
        15: 'Rekel je: »Veš, da je bilo kraljestvo moje in da je ves Izrael svoje obraze naravnal name, da naj bi jaz kraljeval, vendar se je kraljestvo zaobrnilo in postalo bratovo, kajti njegovo je bilo od Gospoda.',
        16: 'Sedaj od tebe prosim eno prošnjo, ne zavrni me.« Rekla mu je: »Povej.«',
        17: 'Rekel je: »Spregovori, prosim te, kralju Salomonu (kajti ne bo ti rekel ne), da mi da za ženo Šunémko Abišágo.«',
        18: 'Batšéba je rekla: »Dobro, zate bom govorila kralju.«',
        19: 'Batšéba je torej šla h kralju Salomonu, da mu govori za Adoníja. Kralj je vstal, da jo sreča in se ji priklonil, se usedel na svoj prestol in dal postaviti sedež za kraljevo mater in usedla se je na njegovo desnico.',
        20: 'Potem je rekla: »Od tebe želim eno majhno prošnjo, prosim te, ne reci mi ne.« Kralj ji je rekel: »Vprašaj, moja mati, kajti jaz ti ne bom rekel ne.«',
        21: 'Rekla je: »Naj bo Šunémka Abišága dana tvojemu bratu Adoníju za ženo.«',
        22: 'Kralj Salomon je odgovoril svoji materi in rekel: »Zakaj prosiš za Adoníja Šunémko Abišágo? Prosi zanj tudi kraljestvo, kajti on je moj starejši brat; celo zanj in za duhovnika Abjatárja in za Cerújinega sina Joába.«',
        23: 'Potem je kralj Salomon prisegel pri Gospodu, rekoč: »Bog naj mi tako stori in še več, če ni Adoníja te besede spregovoril zoper svoje lastno življenje.',
        24: 'Zdaj torej kakor živi Gospod, ki me je utrdil in me postavil na prestol mojega očeta Davida in ki mi je naredil hišo, kakor je obljubil, bo ta dan Adoníja usmrčen.«',
        25: 'Kralj Salomon je poslal po roko Jojadájevega sina Benajá in ta je padel nanj, da je umrl.',
        26: 'Duhovniku Abjatárju pa je kralj rekel: »Pojdi v Anatót, k svojim lastnim poljem, kajti vreden si smrti, toda tokrat te ne bom usmrtil, ker pred mojim očetom Davidom nosiš skrinjo Gospoda Boga in ker si bil prizadet v vsem, s čimer je bil prizadet moj oče.«',
        27: 'Tako je Salomon vrgel ven Abjatárja, da ne bi bil duhovnik Gospodu, da je lahko izpolnil Gospodovo besedo, ki jo je govoril glede Élijeve hiše v Šilu.',
        28: 'Potem so do Joába prišle novice, kajti Joáb se je obrnil za Adoníjem, čeprav se ni obrnil za Absalomom. Joáb je pobegnil h Gospodovemu šotorskemu svetišču in se oprijel oltarnih rogov.',
        29: 'To je bilo povedano kralju Salomonu, da je Joáb pobegnil v Gospodovo šotorsko svetišče in glej, pri oltarju je. Potem je Salomon poslal Jojadájevega sina Benajá, rekoč: »Pojdi, padi nanj.«',
        30: 'Benajá je prišel v Gospodovo šotorsko svetišče ter mu rekel: »Tako govori kralj: ›Pridi naprej.‹« Rekel je: »Ne, temveč bom tukaj umrl.« Benajá je kralju ponovno prinesel besedo, rekoč: »Tako je rekel Joáb in tako mi je odgovoril.«',
        31: 'Kralj mu je rekel: »Stôri, kakor je rekel, padi nanj in ga pokoplji, da boš lahko od mene in od hiše mojega očeta odvzel nedolžno kri, ki jo je prelil Joáb.',
        32: 'Gospod bo njegovo kri povrnil na njegovo lastno glavo, ker je padel na dva moža, pravičnejša in boljša kakor on in ju umoril z mečem, moj oče David pa ni vedel o tem, namreč Nerovega sina Abnêrja, poveljnika Izraelove vojske in Jeterjevega sina Amasája, poveljnika Judove vojske.',
        33: 'Njuna kri se bo torej povrnila na Joábovo glavo in na glavo njegovega semena na veke, toda nad Davidom, nad njegovim semenom, nad njegovo hišo in nad njegovim prestolom bo mir na veke od Gospoda.«',
        34: 'Tako je Jojadájev sin Benajá odšel gor, padel nanj, ga usmrtil in pokopan je bil v svoji lastni hiši v divjini.',
        35: 'Na njegovo mesto, čez vojsko, je kralj postavil Jojadájevega sina Benajá, na Abjatárjevo mesto pa je kralj postavil duhovnika Cadóka.',
        36: 'Kralj je poslal in poklical Šimíja ter mu rekel: »Zgradi si hišo v Jeruzalemu in tam prebivaj in ne hodi kamorkoli od tam.',
        37: 'Kajti tako bo, da na dan, ko pojdeš ven in preideš potok Kidron, boš zagotovo vedel, da boš zagotovo umrl. Tvoja kri bo na tvoji lastni glavi.«',
        38: 'Šimí je rekel kralju: »Ta beseda je dobra, kakor je rekel moj gospod kralj, tako bo tvoj služabnik storil.« In Šimí je mnogo dni prebival v Jeruzalemu.',
        39: 'Pripetilo pa se je ob koncu treh let, da sta dva izmed Šimíjevih služabnikov pobegnila k Maahájevemu sinu Ahíšu, kralju iz Gata. Šimíju so povedali, rekoč: »Glej, tvoja služabnika sta v Gatu.«',
        40: 'Šimí je vstal, osedlal svojega osla in šel v Gat, k Ahíšu, da poišče svoja služabnika. Šimí je odšel in svoja služabnika privedel iz Gata.',
        41: 'To je bilo povedano Salomonu, da je Šimí iz Jeruzalema odšel v Gat in ponovno prišel nazaj.',
        42: 'Kralj je poslal in dal poklicati Šimíja ter mu rekel: »Mar te nisem primoral, da prisežeš pri Gospodu in ti izpričal, rekoč: ›Zagotovo vedi, na dan, ko greš ven in hodiš kakorkoli naokoli, da boš zagotovo umrl?‹ In rekel si mi: ›Beseda, ki sem jo slišal, je dobra.‹',
        43: 'Zakaj se potem nisi držal Gospodove prisege in zapovedi, ki sem ti jo naročil?«',
        44: 'Kralj je poleg tega Šimíju rekel: »Ti poznaš vso zlobnost, ki je znana tvojemu srcu, ki si jo storil mojemu očetu Davidu, zato bo Gospod tvojo zlobnost povrnil na tvojo lastno glavo',
        45: 'in kralj Salomon bo blagoslovljen in Davidov prestol bo pred Gospodom utrjen na veke.«',
        46: 'Tako je kralj zapovedal Jojadájevemu sinu Benajáju, ki je odšel ven in padel nanj, da je ta umrl. In kraljestvo je bilo utrjeno v Salomonovi roki.',
    },
    3: {
        1: 'Salomon je sklenil svaštvo s faraonom, egiptovskim kraljem in vzel faraonovo hčer ter jo privedel v Davidovo mesto, dokler ni končal gradnje svoje lastne hiše, Gospodove hiše in obzidja okoli Jeruzalema.',
        2: 'Vendar pa je ljudstvo žrtvovalo na visokih krajih, ker do tistih dni ni bilo zgrajene hiše Gospodovemu imenu.',
        3: 'Salomon je ljubil Gospoda, hodeč po zakonih svojega očeta Davida, vendar je žrtvoval in zažigal kadilo na visokih krajih.',
        4: 'Kralj je odšel do Gibeóna, da tam žrtvuje, kajti to je bil ugleden visok kraj [in] na tistem oltarju je Salomon daroval tisoč žgalnih daritev.',
        5: 'V Gibeónu se je Gospod v sanjah ponoči prikazal Salomonu in Bog je rekel: »Prosi, kaj naj ti dam.«',
        6: 'Salomon je rekel: »Svojemu služabniku, mojemu očetu Davidu, si izkazal veliko milost, kakor je hodil pred teboj v resnici, v pravičnosti in v iskrenosti srca s teboj in si zanj ohranil to veliko prijaznost, da si mu dal sina, da sedi na njegovem prestolu, kakor je to ta dan.',
        7: 'Sedaj, oh Gospod, moj Bog, svojega služabnika si naredil kralja namesto mojega očeta Davida. Jaz pa sem samo majhen otrok. Ne vem kako odhajati ali prihajati.',
        8: 'Tvoj služabnik je v sredi tvojega ljudstva, ki si ga izbral, velikega ljudstva, ki zaradi množice ne more biti niti našteto niti prešteto.',
        9: 'Daj torej svojemu služabniku razumevajoče srce, da sodi tvoje ljudstvo, da bom lahko razločeval med dobrim in slabim, kajti kdo je zmožen soditi to tvoje tako veliko ljudstvo?«',
        10: 'Govor je ugajal Gospodu, da je Salomon prosil to stvar.',
        11: 'Bog mu je rekel: »Ker si prosil to stvar in zase nisi prosil dolgega življenja, niti zase nisi prosil bogastev, niti nisi prosil za življenja svojih sovražnikov, temveč si zase prosil razumevanje, da razsojaš sodbo;',
        12: 'glej, storil sem glede na tvoje besede, glej, dal sem ti modrost in razumevajoče srce, tako da pred teboj ni bilo nikogar podobnega tebi niti za teboj ne bo vstal nihče podoben tebi.',
        13: 'Dal sem ti tudi to, česar nisi prosil, tako bogastva kakor čast, tako da vse tvoje dni med kralji ne bo nobenega kralja podobnega tebi.',
        14: 'Če boš hodil po mojih poteh, da varuješ moje zakone in moje zapovedi, kakor je hodil tvoj oče David, potem bom podaljšal tvoje dni.«',
        15: 'Salomon se je prebudil in glej, to so bile sanje. Prišel je v Jeruzalem, stopil pred skrinjo Gospodove zaveze in daroval žgalne daritve, mirovne daritve in vsem svojim služabnikom priredil gostijo.',
        16: 'Potem sta prišli h kralju dve ženski, ki sta bili pocestnici in obstali pred njim.',
        17: 'Ena ženska je rekla: »Oh moj gospod, jaz in ta ženska stanujeva v eni hiši in rodila sem otroka, z njo v hiši.',
        18: 'Tretji dan pa se je pripetilo, potem ko sem rodila, da je tudi ta ženska rodila in bili sva skupaj. Z nama v hiši ni bilo nobenega tujca, razen naju dveh v hiši.',
        19: 'Otrok te ženske pa je ponoči umrl, ker ga je prekrila.',
        20: 'Ona pa je opolnoči vstala in mojega sina vzela od mene, medtem ko je tvoja pomočnica spala in si ga položila v svoje naročje, svojega mrtvega pa je položila v moje naročje.',
        21: 'Ko sem zjutraj vstala, da podojim svojega otroka, glej, je bil ta mrtev. Toda ko sem to zjutraj preudarjala, glej, to ni bil moj sin, ki sem ga rodila.«',
        22: 'Druga ženska pa je rekla: »Ne, temveč živi je moj sin, mrtvi pa je tvoj sin.« Ta pa je rekla: »Ne, temveč mrtvi je tvoj sin, živi pa je moj sin.« Tako sta govorili pred kraljem.',
        23: 'Potem je kralj rekel: »Ena pravi: ›Ta je moj sin, ki živi, tvoj sin pa je mrtev.‹ Druga pa pravi: ›Ne, temveč je mrtvi tvoj sin, moj sin pa živi.‹«',
        24: 'Kralj je rekel: »Prinesite mi meč.« Meč so prinesli pred kralja.',
        25: 'Kralj je rekel: »Živega otroka razdelite na pol in polovico dajte eni, polovico pa drugi.«',
        26: 'Potem je kralju spregovorila ženska, od katere je bil živi otrok, kajti njena notranjost je hrepenela za svojim sinom in rekla: »Oh moj gospod, izročite ji živega otroka in nikakor ga ne ubijte.« Druga pa je rekla: »Naj ne bo niti moj niti tvoj, temveč ga razdelite.«',
        27: 'Potem je kralj odgovoril in rekel: »Njej dajte živega otroka in ga nikakor ne ubijte. Ona je njegova mati.«',
        28: 'Ves Izrael je slišal o sodbi, ki jo je kralj razsodil in bali so se kralja, kajti videli so, da je bila v njem Božja modrost, da razsoja.',
    },
    4: {
        1: 'Tako je bil kralj Salomon kralj nad vsem Izraelom.',
        2: 'To so bili princi, ki jih je imel: Azarjá, sin duhovnika Cadóka;',
        3: 'Šišájeva sinova Elihóref in Ahíja, pisarja; Ahilúdov sin Józafat, letopisec;',
        4: 'Jojadájev sin Benajá je bil nad vojsko; Cadók in Abjatár sta bila duhovnika;',
        5: 'Natánov sin Azarjá, je bil nad častniki; Natánov sin Zabúd je bil glavni častnik in kraljev prijatelj;',
        6: 'Ahišár je bil nad družino in Abdájev sin Adonirám je bil nad davkom.',
        7: 'Salomon je imel dvanajst častnikov nad vsem Izraelom, ki so zagotavljali živež za kralja in njegovo družino. Vsak človek je v svojem mesecu leta pripravljal preskrbo.',
        8: 'To so njihova imena: Hurov sin na gori Efrájim;',
        9: 'Dekerjev sin v Makácu, Šaalbímu, Bet Šemešu in Elón Bet Hanánu;',
        10: 'Hesedov sin v Arubótu – njemu je pripadal Sohó in vsa Heferjeva dežela;',
        11: 'Abinadábov sin v vseh področjih Dora, ki je imel za ženo Salomonovo hčer Tafáto;',
        12: 'Ahilúdov sin Baaná – njemu so pripadali Taanáh, Megída in ves Bet Šeán, ki je pri Caretánu pod Jezreélom, od Bet Šeána do Abél Mehóle, celó do kraja, ki je onkraj Jokneáma;',
        13: 'Geberjev sin v Ramót Gileádu – njemu so pripadala mesta Manásejevega sina Jaíra, ki so v Gileádu, njemu je pripadalo tudi območje Argóba, ki je v Bašánu, šestdeset velikih mest z obzidji in bronastimi zapahi;',
        14: 'Idójev sin Ahinadáb je imel Mahanájim;',
        15: 'Ahimáac je bil v Neftáliju, za ženo je vzel tudi Salomonovo hčer Basemáto;',
        16: 'Hušájev sin Baaná je bil v Aserju in v Alótu;',
        17: 'Parúahov sin Józafat v Isahárju;',
        18: 'Elájev sin Šimí v Benjaminu;',
        19: 'Uríjev sin Geber je bil v deželi Gileád, v deželi amoréjskega kralja Sihóna in bašánskega kralja Oga in ta je bil edini častnik, ki je bil v deželi.',
        20: 'Juda in Izrael sta bila številna, tako obilna, kakor je peska ob morju; jedli so, pili in se veselili.',
        21: 'Salomon je kraljeval nad vsemi kraljestvi od reke do filistejske dežele in do egiptovske meje. Prinašali so darila in vse dni svojega življenja služili Salomonu.',
        22: 'Salomonova preskrba za en dan je bila trideset mer fine moke, šestdeset mer moke,',
        23: 'deset rejenih volov, dvajset volov s pašnikov in sto ovc, poleg jelenov, srnjakov, damjakov in pitane perjadi.',
        24: 'Kajti imel je gospostvo nad vsem področjem na tej strani reke, od Tifsáha celo do Gaze, nad vsemi kralji na tej strani reke, in imel je mir na vseh straneh okoli sebe.',
        25: 'Juda in Izrael sta prebivala varno, vsak mož pod svojo trto in pod svojim figovim drevesom, od Dana, celo do Beeršébe, vse Salomonove dni.',
        26: 'Salomon je imel štirideset tisoč konjskih boksov za svoje bojne vozove in dvanajst tisoč konjenikov.',
        27: 'Ti častniki so zagotavljali živež za kralja Salomona in za vse, ki so prišli k Salomonovi mizi, vsak mož v svojem mesecu. Ničesar jim ni primanjkovalo.',
        28: 'Tudi ječmen in slamo za konje in [enogrbe] velblode so prinašali na kraj, kjer so bili častniki, vsak moški glede na svojo zadolžitev.',
        29: 'Bog je dal Salomonu modrost in razumevanje, silno mnogo in širino srca, celo kakor je peska, ki je na morski obali.',
        30: 'Salomonova modrost je presegala modrost vseh otrok vzhodne dežele in vso modrost Egipta.',
        31: 'Kajti bil je modrejši od vseh ljudi; od Ezráhovca Etána in Mahólovih sinov, Hemána, Kalkóla in Dardá in njegov sloves je bil v vseh narodih naokrog.',
        32: 'Izrekel je tri tisoč pregovorov in njegovih pesmi je bilo tisoč in pet.',
        33: 'Govoril je o drevesih, od cedrovega drevesa, ki je na Libanonu, celo do izopa, ki poganja iz zidu. Govoril je tudi o živini, o perjadi, o plazečih stvareh in o ribah.',
        34: 'In tja so prihajali iz vseh ljudstev, da poslušajo Salomonovo modrost, od vseh zemeljskih kraljev, ki so slišali o njegovi modrosti.',
    },
    5: {
        1: 'Tirski kralj Hirám je svoje služabnike poslal k Salomonu, kajti slišal je, da so ga mazilili [za] kralja namesto njegovega očeta, kajti Hirám je bil vedno Davidov oboževalec.',
        2: 'Salomon je poslal k Hirámu, rekoč:',
        3: '»Ti veš, da moj oče David ni mogel zgraditi hiše imenu Gospoda, svojega Boga, zaradi vojn, ki so bile okoli njega na vsaki strani, dokler jih ni Gospod položil pod podplate njegovih stopal.',
        4: 'Toda sedaj mi je Gospod, moj Bog, dal počitek na vsaki strani, tako da ni niti nasprotnika niti zlih dogodkov.',
        5: 'Glej, namenil sem se zgraditi hišo imenu Gospoda, svojega Boga, kakor je Gospod spregovoril mojemu očetu Davidu, rekoč: ›Tvoj sin, ki ga bom namesto tebe postavil na tvoj prestol, on bo zgradil hišo mojemu imenu.',
        6: 'Zdaj torej zapovej, da mi iz Libanona posekajo cedrova drevesa in moji služabniki bodo s tvojimi služabniki in dal ti bom plačilo za tvoje služabnike, glede na vse, kar mi boš določil; kajti veš, da med nami ni nobenega, ki tako vešče seka les kot Sidónci.‹«',
        7: 'Ko je Hirám slišal Salomonove besede, se je pripetilo, da se je silno razveselil in rekel: »Blagoslovljen bodi ta dan Gospod, ki je Davidu dal modrega sina nad tem velikim ljudstvom.«',
        8: 'In Hirám je poslal k Salomonu, rekoč: »Preudaril sem stvari, zaradi katerih pošiljaš k meni in izpolnil bom vso tvojo željo glede cedrovega lesa in glede cipresovega lesa.',
        9: 'Moji služabniki ga bodo spravljali dol iz Libanona do morja in po morju ga bom spravljal v splavih na mesto, ki mi ga boš določil in povzročim jim, da bodo tam razvezani in jih boš sprejel, ti pa boš izpolnil mojo željo, da mi daješ hrano za mojo družino.«',
        10: 'Tako je Hirám dajal Salomonu cedrov les in cipresov les glede na vse njegove želje.',
        11: 'Salomon je dajal Hirámu dvajset tisoč mer pšenice za hrano njegovi družini in dvajset mer čistega olja. Tako je Salomon dajal Hirámu leto za letom.',
        12: 'Gospod je dal Salomonu modrost, kakor mu je obljubil in bil je mir med Hirámom in Salomonom in onadva sta sklenila zavezo.',
        13: 'Kralj Salomon je zbral dajatev obveznega dela iz vsega Izraela, in dajatev obveznega dela je bila trideset tisoč mož.',
        14: 'Pošiljal jih je k Libanonu, deset tisoč na mesec, v izmenah. En mesec so bili na Libanonu in dva meseca doma. Adonirám pa je bil nad dajatvijo obveznega dela.',
        15: 'Salomon jih je imel sedemdeset tisoč, ki so nosili bremena in osemdeset tisoč sekalcev v gorah,',
        16: 'poleg glavnih Salomonovih častnikov, ki so bili nad delom, tri tisoč tristo, ki so vladali nad ljudstvom, ki je opravljalo delo.',
        17: 'Kralj je zapovedal in prinesli so velike kamne, drage kamne, klesane kamne, da hiši položijo temelj.',
        18: 'Salomonovi graditelji, Hirámovi graditelji in kamnoseki so jih klesali. Tako so pripravili les in kamne, da zgradijo hišo.',
    },
    6: {
        1: 'Pripetilo se je v štiristo osemdesetem letu, potem ko so Izraelovi otroci izšli iz egiptovske dežele, v četrtem letu Salomonovega kraljevanja nad Izraelom, v mesecu zivu, ki je drugi mesec, da je začel graditi Gospodovo hišo.',
        2: 'Dolžina hiše, ki jo je kralj Salomon gradil za Gospoda, je bila šestdeset komolcev, njena širina dvajset komolcev in njena višina trideset komolcev.',
        3: 'Dolžina preddverja pred hišnim templjem je bila dvajset komolcev, glede na širino hiše in deset komolcev je bila njegova širina pred hišo.',
        4: '§ Za hišo je naredil okna ozkih luči.',
        5: 'Ob zidu hiše naokoli je zgradil sobe, ob zidovih hiše naokoli, tako od templja in od oraklja. Naredil je sobe naokoli.',
        6: 'Najnižja soba je bila pet komolcev široka, srednja je bila šest komolcev široka in tretja je bila sedem komolcev široka, kajti zunaj, v zidu hiše je naokoli naredil ozke opore, da bruna ne bi bila pritrjena v zidove hiše.',
        7: 'Hiša, ko je bila ta v gradnji, je bila grajena iz pripravljenega kamna, preden je bil ta pripeljan tja, tako da tam v hiši ni bilo slišati niti kladiva niti sekire niti nobenega orodja iz železa, ko je bila ta v gradnji.',
        8: 'Vrata za srednjo sobo so bila na desni strani hiše. Gor so šli po zavitih stopnicah v srednjo sobo in iz srednje sobe v tretjo.',
        9: 'Tako je gradil hišo in jo dokončal in hišo pokril z bruni in cedrovimi deskami.',
        10: 'Potem je zgradil sobe ob vsej hiši, pet komolcev visoke in na hišo so bile pritrjene s cedrovim lesom.',
        11: 'Gospodova beseda je prišla Salomonu, rekoč:',
        12: '» Glede te hiše, ki jo gradiš, če se boš ravnal po mojih zakonih in izvajal moje sodbe in varoval vse moje zapovedi, da se ravnaš po njih, potem bom s teboj izvršil svojo besedo, ki sem jo govoril tvojemu očetu Davidu.',
        13: 'Prebival bom med Izraelovimi otroki in ne bom zapustil svojega ljudstva Izraela.«',
        14: 'Tako je Salomon zgradil hišo in jo dokončal.',
        15: 'Zidove hiše znotraj je obložil s cedrovimi deskami, tako tla hiše kakor zidove stropa. In znotraj jih je pokril z lesom in tla hiše pokril s cipresovimi deskami.',
        16: 'Obložil je dvajset komolcev na straneh hiše, tako tla kakor stene s cedrovimi deskami. Zanjo jih je torej zgradil znotraj, torej za orakelj, torej za najsvetejši kraj.',
        17: 'Hiša, to je tempelj pred njo, je bila dolga štirideset komolcev.',
        18: 'Cedrovina hiše znotraj je bila izrezljana s popki in odprtimi cvetovi. Vse je bilo iz cedrovine; nobenega kamna ni bilo videti.',
        19: 'Orakelj je pripravil znotraj v hiši, da tja postavi Gospodovo skrinjo zaveze.',
        20: 'Orakelj v sprednjem delu je bil dvajset komolcev po dolžini in dvajset komolcev po širini in dvajset komolcev po njegovi višini. Prevlekel ga je s čistim zlatom in tako je pokril oltar, ki je bil iz cedrovine.',
        21: 'Tako je Salomon hišo prevlekel s čistim zlatom. Pred orakljem je naredil prehode z verižicami iz zlata in to prevlekel z zlatom.',
        22: 'Celotno hišo je prevlekel z zlatom, dokler ni dokončal vse hiše. Prav tako je celoten oltar, ki je bil poleg oraklja, prevlekel z zlatom.',
        23: 'Znotraj oraklja je naredil dva keruba iz oljkovega lesa, vsakega deset komolcev visokega.',
        24: 'Pet komolcev je merila ena kerubova perut in pet komolcev je bila druga kerubova perut. Od zadnjega dela ene peruti do zadnjega dela druge je bilo deset komolcev.',
        25: 'Drugi kerub je meril deset komolcev. Oba keruba sta bila ene mere in ene velikosti.',
        26: 'Višina enega keruba je bila deset komolcev in takšna je bila ta od drugega keruba.',
        27: 'Keruba je postavil znotraj notranje hiše. Peruti kerubov so se razprostirala tako, da se je perut enega dotaknila ene stene in perut drugega keruba se je dotaknila druge stene in njuni peruti sta se dotikali druga druge v sredi hiše.',
        28: 'Keruba je prevlekel z zlatom.',
        29: 'Vse hišne stene naokoli je izrezljal z izrezljanimi figurami kerubov, palmovih dreves in odprtih cvetov, znotraj in zunaj.',
        30: 'Tla hiše je prevlekel z zlatom, znotraj in zunaj.',
        31: 'Za vhod oraklja je naredil vrata iz oljkovega lesa. Vratna preklada in podboja sta bila petino zidu.',
        32: 'Tudi dve vrati sta bili iz oljkovega lesa in nanju je izrezljal rezljanja kerubov, palmovih dreves in odprtih cvetov in jih prevlekel z zlatom in zlato razširil nad keruba in nad palmova drevesa.',
        33: 'Tako je tudi za tempeljska vrata naredil podboje iz oljkovega lesa, četrtino zidu.',
        34: 'Dve vrati sta bili iz cipresovega lesa. Dve vratnici enih vrat sta bili pregibni in dve vratnici drugih vrat sta bili pregibni.',
        35: 'Nanje je izrezljal kerube, palmova drevesa in odprte cvetove. Prevlekel jih z zlatom, ki se je prilegal izrezljanemu delu.',
        36: 'Notranji dvor je zgradil s tremi vrstami klesanega kamna in vrsto cedrovih brun.',
        37: 'V četrtem letu, v mesecu zivu, je bil položen temelj Gospodovi hiši.',
        38: 'V enajstem letu, v mesecu bulu, ki je osmi mesec, je bila hiša dokončana v vseh njenih delih in glede na ves njen videz. Tako je bila v gradnji sedem let.',
    },
    7: {
        1: 'Toda Salomon je svojo lastno hišo gradil trinajst let in dokončal vso svojo hišo.',
        2: 'Zgradil je tudi hišo libanonskega gozda; njena dolžina je bila sto komolcev, njena širina petdeset komolcev in njena višina trideset komolcev, na štirih vrstah cedrovih stebrov, s cedrovimi bruni na stebrih.',
        3: 'Ta je bila pokrita s cedrovino zgoraj na brunih, ki so ležala na petinštiridesetih stebrih, [po] petnajst v vrsti.',
        4: 'Tam so bila okna v treh vrstah in svetloba je bila nasproti svetlobi v treh vrstah.',
        5: 'Vsa vrata in podboji so bili štirioglati, z okni in svetloba je bila nasproti svetlobi v treh vrstah.',
        6: 'Naredil je preddverje iz stebrov. Njegova dolžina je bila petdeset komolcev in njegova širina trideset komolcev. Preddverje je bilo pred njimi; in drugi stebri in debela bruna so bila pred njimi.',
        7: 'Potem je naredil preddverje za prestol, kjer bi lahko sodil, celó preddverje sodbe. To je bilo prekrito s cedrovino od ene strani tal do druge.',
        8: 'Hiša, v kateri je prebival, je imela drug dvor znotraj preddverja, ki je bilo iz podobnega dela. Salomon je naredil tudi hišo za faraonovo hčer, ki si jo je vzel za ženo, podobno temu preddverju.',
        9: 'Vse te so bile iz dragih kamnov, glede na mere klesanih kamnov, žagane z žagami, zunaj in znotraj, celo od temelja do napušča in tako na zunanji strani proti velikemu dvoru.',
        10: 'Temelj je bil iz dragih kamnov, celo velikih kamnov, kamnov desetih komolcev in kamnov osmih komolcev.',
        11: 'Zgoraj so bili dragi kamni, po meri klesanih kamnov in cedrovina.',
        12: 'Velik dvor naokoli je bil s tremi vrstami klesanih kamnov in vrsto cedrovih brun, tako za notranji dvor Gospodove hiše in za preddverje hiše.',
        13: 'Kralj Salomon je poslal in Hiráma pripeljal iz Tira.',
        14: 'Bil je vdovin sin iz Neftálijevega rodu, njegov oče pa je bil mož iz Tira, delavec v bronu. Napolnjen je bil z modrostjo, razumevanjem in spretnostjo, da opravlja vsa dela z bronom. Prišel je h kralju Salomonu in opravil vse njegovo delo.',
        15: 'Kajti vlil je dva stebra iz brona, vsakega po osemnajst komolcev visokega in vrvica dvanajstih komolcev je naokoli obdajala vsakega izmed njiju.',
        16: 'Naredil je dva kapitela iz vlitega brona, da ju postavi na vrhova stebrov. Višina enega kapitela je bila pet komolcev in višina drugega kapitela je bila pet komolcev.',
        17: 'In mreže iz narejenih zank in spleten verižni del za kapitele, ki so bili na vrhu stebrov; sedem za en kapitel in sedem za drug kapitel.',
        18: 'Naredil je stebre in dve vrsti naokoli na eni mreži, da z granatnimi jabolki pokrije kapitele, ki so bili na vrhu. Tako je storil tudi za drugi kapitel.',
        19: 'Kapitela, ki sta bila na vrhu stebrov v preddverju, sta bila iz lilijastega dela, štiri komolce.',
        20: 'Kapitela na dveh stebrih sta imela granatna jabolka tudi zgoraj, nasproti vdolbini, ki je bila pri mreži. Granatnih jabolk je bilo dvesto v vrstah naokoli na drugem kapitelu.',
        21: 'Stebra je postavil v preddverju templja. Postavil je desni steber in ga imenoval Jahín, in postavil je levi steber ter njegovo ime imenoval Boaz',
        22: 'Na vrhu stebrov je bilo lilijasto delo. Tako je bilo delo stebrov dokončano.',
        23: 'Naredil je ulito morje, deset komolcev od enega robu, do drugega. To je bilo naokoli okroglo in njegova višina je bila pet komolcev. Vrvica tridesetih komolcev ga je obkrožila naokoli.',
        24: 'Pod njegovim robom naokoli so bili popki, ki so ga obdajali, deset na komolec, ki so naokoli obdajali morje. Popki so bili uliti v dveh vrstah, ko je bilo to ulito.',
        25: 'To je stalo na dvanajstih volih; trije so gledali proti severu, trije so gledali proti zahodu, trije so gledali proti jugu in trije so gledali proti vzhodu. Morje je bilo postavljeno zgoraj na njih in vsi njihovi zadnji deli so bili [obrnjeni] navznoter.',
        26: 'To je bilo za širino roke debelo in njegov rob je bil izdelan kakor rob čaše, s cvetovi lilij. Vseboval je dva tisoč čebrov.',
        27: 'Naredil je deset podstavkov iz brona; štiri komolce je bila dolžina enega podstavka, štiri komolce je bila njegova širina in tri komolce njegova višina.',
        28: 'Delo podstavkov je bilo na ta način: imeli so robove in robovi so bili med ploskvami.',
        29: 'Na robovih, ki so bili med ploskvami, so bili levi, voli in kerubi. Na ploskvah je bil zgoraj podstavek in spodaj pod levi in voli so bili nekateri dodatki, narejeni iz tankega dela.',
        30: 'Vsak podstavek je imel štiri bronasta kolesa in bronaste osi. Njegovi štirje vogali so imeli opornike. Pod [okroglim] umivalnikom so bili oporniki uliti, pri strani vsakega dodatka.',
        31: 'Odprtina le-tega znotraj kapitela in nad njim je bila komolec, toda odprtina le-tega je bila okrogla po delu podstavka, komolec in pol. Prav tako so bili na njegovi odprtini reliefi s svojimi robovi, štirioglati, neokrogli.',
        32: 'Pod robovi so bila štiri kolesa in držaji koles so bili pritrjeni k podstavku. Višina kolesa je bila komolec in pol.',
        33: 'Delo koles je bilo podobno delu kolesa bojnega voza. Njihovi držaji, njihova platišča, njihove napere in njihova pesta so bila vsa ulita.',
        34: 'Bili so štirje oporniki k štirim vogalom enega podstavka in oporniki so bili del samega podstavka.',
        35: 'Na vrhu podstavka je bil zaokrožen krog, pol komolca visok in na vrhu podstavka so bile njegove ploskve in njegovi robovi iz istega.',
        36: 'Kajti na oseh ploskev in na njegovih robovih je izrezljal kerube, leve in palmova drevesa, glede na razmerja vsakega in dodatke naokoli.',
        37: 'Na ta način je naredil deset podstavkov. Vsi izmed njih so imeli en ulitek, eno mero in eno velikost.',
        38: 'Potem je naredil deset [okroglih] bronastih umivalnikov. En [okrogel] umivalnik je vseboval štirideset čebrov. In vsak [okrogel] umivalnik je imel štiri komolce in na vsakem izmed desetih podstavkov en [okrogel] umivalnik.',
        39: 'Pet podstavkov je postavil na desno stran hiše in pet na levo stran hiše. Morje je postavil na desno stran hiše, proti vzhodu, nasproti jugu.',
        40: 'Hirám je naredil [okrogle] umivalnike, lopate in umivalnike. Tako je Hirám naredil konec vseh del, ki jih je kralj Salomon storil za Gospodovo hišo:',
        41: 'dva stebra; dve skledi iz kapitelov, ki sta bili na vrhu dveh stebrov; dve mreži, da pokrijeta dve skledi kapitelov, ki sta bili na vrhu stebrov;',
        42: 'štiristo granatnih jabolk za dve mreži, celó dve vrsti granatnih jabolk za eno mrežo, da pokrijejo dve skledi kapitelov, ki sta bili na stebrih;',
        43: 'deset podstavkov; deset [okroglih] umivalnikov na podstavkih;',
        44: 'eno morje in dvanajst volov pod morjem;',
        45: 'lonce; lopate in umivalnike. Vse te posode, ki jih je Hirám naredil kralju Salomonu za Gospodovo hišo, so bile iz svetlega brona.',
        46: 'Na jordanski ravnini jih je kralj ulil, na ilovnati zemlji med Sukótom in Caretánom.',
        47: 'Salomon je pustil vse posode nestehtane, ker jih je bilo silno mnogo. Niti niso ugotovili teže brona.',
        48: 'Salomon je naredil vse posode, ki so pripadale Gospodovi hiši: zlat oltar in zlato mizo, na kateri je bil hleb navzočnosti;',
        49: 'svečnike iz čistega zlata, pet na desni strani in pet na levi, pred orakljem, s cvetovi, svetilkami in utrinjači iz zlata;',
        50: 'sklede; utrinjala; umivalnike; žlice; kadilnice iz čistega zlata in tečaje iz zlata, tako za vrata notranje hiše najsvetejšega kraja in za vrata hiše, namreč od templja.',
        51: 'Tako je bilo dokončano vse delo, ki ga je kralj Salomon naredil za Gospodovo hišo. Salomon je prinesel noter stvari, ki jih je posvetil njegov oče David, torej srebro, zlato in posode je položil med zaklade Gospodove hiše.',
    },
    8: {
        1: 'Potem je Salomon zbral Izraelove starešine in vse poglavarje rodov, vodilne izmed očetov Izraelovih otrok, h kralju Salomonu v Jeruzalem, da bi lahko prinesli gor skrinjo Gospodove zaveze iz Davidovega mesta, ki je Sion.',
        2: 'Vsi možje iz Izraela so se na praznik zbrali h kralju Salomonu, v mesecu etanímu, ki je sedmi mesec.',
        3: 'Prišli so vsi Izraelovi starešine in duhovniki so dvignili skrinjo.',
        4: 'Gor so prinesli Gospodovo skrinjo, šotorsko svetišče skupnosti shoda in vse svete posode, ki so bile v šotorskem svetišču, celo te so duhovniki in Lévijevci prinesli gor.',
        5: 'Kralj Salomon in vsa Izraelova skupnost, ki je bila zbrana k njemu, so bili z njim pred skrinjo. Žrtvovali so ovce in vole, ki se jih zaradi množice ni dalo ne povedati ne prešteti.',
        6: 'Duhovniki so skrinjo Gospodove zaveze prinesli na njeno mesto, v hišni orakelj, k najsvetejšemu kraju, celo pod peruti kerubov.',
        7: 'Kajti keruba sta svoji dve peruti razprostirala nad prostorom skrinje in keruba sta od zgoraj pokrivala skrinjo in njena drogova.',
        8: 'Drogova so izvlekli, da sta se konca drogov videla iz svetega kraja pred orakljem, odzunaj pa nista bila vidna in tam sta do današnjega dne.',
        9: 'V skrinji ni bilo ničesar razen dveh kamnitih plošč, ki ju je Mojzes položil tja pri Horebu, ko je Gospod sklenil zavezo z Izraelovi otroci, ko so prišli iz egiptovske dežele.',
        10: 'Pripetilo se je, ko so duhovniki prišli ven iz svetega kraja, da je oblak napolnil Gospodovo hišo,',
        11: 'tako da duhovniki zaradi oblaka niso mogli stati, da bi služili, kajti Gospodova slava je napolnila Gospodovo hišo.',
        12: 'Potem je spregovoril Salomon: » Gospod je rekel, da bo prebival v gosti temi.',
        13: 'Zagotovo sem ti zgradil hišo, da prebivaš v njej, ustaljen kraj zate, da v njem prebivaš na veke.«',
        14: 'Kralj je obrnil svoj obraz naokrog in blagoslovil vso Izraelovo skupnost (in vsa Izraelova skupnost je stala)',
        15: 'in rekel je: »Blagoslovljen bodi Gospod, Izraelov Bog, ki je s svojimi usti spregovoril mojemu očetu Davidu in je to izpolnil s svojo roko, rekoč:',
        16: '›Od dneva, ko sem svoje ljudstvo Izraela privedel ven iz Egipta, nisem izbral nobenega mesta izmed vseh Izraelovih rodov, da bi zgradil hišo, da bi bilo v njej lahko moje ime, temveč sem izbral Davida, da bo nad mojim ljudstvom Izraelom.‹',
        17: 'To je bilo na srcu mojega očeta Davida, da zgradi hišo za ime Gospoda, Izraelovega Boga.',
        18: 'Gospod je rekel mojemu očetu Davidu: ›Medtem ko je bilo to v tvojem srcu, da zgradiš hišo mojemu imenu, si storil dobro, da je bilo to v tvojem srcu.',
        19: 'Vendar pa hiše ne boš gradil ti, temveč tvoj sin, ki bo izšel iz tvojih ledij, on bo zgradil hišo mojemu imenu.‹',
        20: 'Gospod je izpolnil svojo besedo, ki jo je govoril in dvignjen sem bil na položaj svojega očeta Davida in sedim na Izraelovem prestolu, kakor je obljubil Gospod in zgradil sem hišo za ime Gospoda, Izraelovega Boga.',
        21: 'Tam sem pripravil prostor za skrinjo, v kateri je Gospodova zaveza, ki jo je on sklenil z našimi očeti, ko jih je privedel ven iz egiptovske dežele.«',
        22: 'Salomon je stal pred Gospodovim oltarjem v prisotnosti vse Izraelove skupnosti in svoji roki razširil proti nebu',
        23: 'in rekel: » Gospod, Izraelov Bog, ni Boga, podobnega tebi, na nebu zgoraj ali na zemlji spodaj, ki ohranjaš zavezo in usmiljenje s svojimi služabniki, ki z vsem svojim srcem hodijo pred teboj,',
        24: 'ki si svojemu služabniku Davidu, mojemu očetu, ohranil to, kar si mu obljubil. Govoril si s svojimi usti in si to tudi izpolnil s svojo roko, kakor je to ta dan.',
        25: 'Zato zdaj Gospod, Izraelov Bog, ohrani s svojim služabnikom Davidom, mojim očetom, to, kar si mu obljubil, rekoč: ›Ne bo ti zmanjkalo moža v mojem pogledu, da bi sedel na Izraelovem prestolu; samo da tvoji otroci pazijo na svojo pot, da hodijo pred menoj, kakor si ti hodil pred menoj.‹',
        26: 'Sedaj, oh Izraelov Bog, naj bo tvoja beseda, prosim te, resnična, ki si jo govoril svojemu služabniku, mojemu očetu Davidu.',
        27: 'Toda ali bo Bog zares prebival na zemlji? Glej, nebo in nebesa nebes te ne morejo obseči, kako veliko manj ta hiša, ki sem jo zgradil?',
        28: 'Vendar se ozri na molitev svojega služabnika in k njegovi ponižni prošnji, oh Gospod, moj Bog, da prisluhneš klicu in molitvi, ki jo ta dan tvoj služabnik moli pred teboj,',
        29: 'da bodo tvoje oči lahko ponoči in podnevi odprte proti tej hiši, torej proti kraju, o katerem si rekel: ›Moje ime bo tam,‹ da boš lahko prisluhnil molitvi, ki jo bo tvoj služabnik naredil k temu kraju.',
        30: 'Prisluhni ponižni prošnji svojega služabnika in svojega ljudstva Izraela, ko bodo molili k temu kraju. Pozorno poslušaj v nebesih, svojem prebivališču. In ko si pozorno slišal, odpusti.',
        31: 'Če se katerikoli človek prekrši zoper svojega bližnjega in je nanj položena prisega, da mu povzroči, da priseže in prisega pride pred tvoj oltar v tej hiši,',
        32: 'potem pozorno poslušaj v nebesih, ukrepaj in sodi svoja služabnika, obsodi zlobnega, da privedeš njegovo pot na njegovo glavo in opraviči pravičnega, da mu daš glede na njegovo pravičnost.',
        33: 'Ko bo tvoje ljudstvo Izrael udarjeno pred sovražnikom, ker so grešili zoper tebe in se bo ponovno obrnilo k tebi, priznalo tvoje ime, molilo in naredilo ponižno prošnjo k tebi v tej hiši,',
        34: 'potem pozorno poslušaj v nebesih in odpusti greh svojega ljudstva Izraela in jih ponovno privedi v deželo, ki jo daješ njihovim očetom.',
        35: 'Ko je nebo zaprto in ni dežja, ker so grešili zoper tebe; če molijo k temu kraju in priznajo tvoje ime in se obrnejo od svojega greha, ko si jih ti prizadel,',
        36: 'potem pozorno poslušaj v nebesih in odpusti greh svojih služabnikov in svojega ljudstva Izraela, da jih naučiš dobro pot, po kateri naj bi hodili in jim daš dež na svojo deželo, ki si jo dal svojemu ljudstvu v dediščino.',
        37: 'Če bo v deželi lakota, če bo kužna bolezen, kvarjenje, plesen, leteča kobilica ali če bo tam gosenica; če jih njihov sovražnik oblega v deželi njihovih mest, kakršnakoli nadloga, kakršnakoli bolezen bo,',
        38: 'kakršnokoli molitev in ponižno prošnjo bo naredil katerikoli človek ali vse tvoje ljudstvo Izrael, ki bo spoznal, vsak mož nadlogo svojega lastnega srca in bo svoje roke razširil proti tej hiši,',
        39: 'potem pozorno poslušaj v nebesih, svojem prebivališču, odpusti, ukrepaj in daj vsakemu možu glede na njegove poti, čigar srce poznaš (kajti ti, celó le ti, poznaš srca vseh človeških otrok),',
        40: 'da se te bodo lahko bali vse dni, ki jih živijo v deželi, ki si jo dal našim očetom.',
        41: 'Poleg tega glede tujca, ki ni iz tvojega ljudstva Izraela, temveč zaradi tvojega imena prihaja iz daljne dežele',
        42: '(kajti slišali bodo o tvojem velikem imenu, o tvoji močni roki in o tvojem iztegnjenem laktu), ko bo prišel in molil k tej hiši,',
        43: 'pozorno poslušaj v nebesih, svojem bivališču in ukrepaj glede na vse, za kar bo tujec klical k tebi, da bo vse ljudstvo zemlje lahko spoznalo tvoje ime, da se te boji, kakor to dela tvoje ljudstvo Izrael in da bodo lahko vedeli, da je ta hiša, ki sem jo zgradil, imenovana po tvojem imenu.',
        44: 'Če gre tvoje ljudstvo ven na bitko zoper svojega sovražnika, kamorkoli jih boš poslal in bodo molili h Gospodu, k mestu, ki si ga ti izbral in k hiši, ki sem jo zgradil za tvoje ime,',
        45: 'potem pozorno poslušaj v nebesih njihovo molitev, njihovo ponižno prošnjo in obravnavaj njihov primer.',
        46: 'Če grešijo zoper tebe (kajti tam ni človeka, ki ne greši) in si jezen nanje in jih izročiš sovražniku, tako da jih odvedejo ujetnike v deželo sovražnika, daleč ali blizu,',
        47: 'vendar če si bodo premislili v deželi, kamor so bili odvedeni ujeti in se pokesajo in naredijo ponižno prošnjo k tebi, v deželi tistih, ki so jih odvedli ujete, rekoč: ›Grešili smo in storili pokvarjeno, zagrešili smo zlobnost‹',
        48: 'in se tako vrnejo k tebi z vsem svojim srcem in z vso svojo dušo v deželi svojih sovražnikov, ki so jih odvedli ujete in molijo k tebi, k svoji deželi, ki si jo dal njihovim očetom, mestu, ki si ga ti izbral in hiši, ki sem jo zgradil za tvoje ime,',
        49: 'potem pozorno poslušaj njihovo molitev in njihovo ponižno prošnjo v nebesih, svojem prebivališču in obravnavaj njihov primer',
        50: 'in odpusti svojemu ljudstvu, ker so grešili zoper tebe in vse njihove prestopke, s katerimi so se prekršili zoper tebe in jim daj sočutje pred tistimi, ki so jih odvedli ujete, da bodo lahko imeli sočutje do njih,',
        51: 'kajti oni so tvoje ljudstvo in tvoja dediščina, ki si jo privedel iz Egipta, iz srede železne talilne peči,',
        52: 'da bodo tvoje oči lahko odprte k ponižni prošnji tvojega služabnika in k ponižni prošnji tvojega ljudstva Izraela, da jim prisluhneš v vsem, v čemer kličejo k tebi.',
        53: 'Kajti oddvojil si jih izmed vsega zemeljskega ljudstva, da bi bili tvoja dediščina, kakor si govoril po roki svojega služabnika Mojzesa, ko si naše očete privedel iz Egipta, oh Gospod Bog.«',
        54: 'Bilo je tako, ko je Salomon nehal moliti vso to molitev in ponižno prošnjo h Gospodu, da je vstal izpred Gospodovega oltarja od klečanja na svojih kolenih, s svojima rokama, razširjenima k nebu.',
        55: 'Vstal je in z močnim glasom blagoslovil vso Izraelovo skupnost, rekoč:',
        56: '»Blagoslovljen bodi Gospod, ki je svojemu ljudstvu Izraelu dal počitek, glede na vse, kar je obljubil. Niti ena beseda ni manjkala od vse njegove dobre obljube, ki jo je obljubil po roki svojega služabnika Mojzesa.',
        57: 'Gospod, naš Bog, naj bo z nami, kakor je bil z našimi očeti. Naj nas ne pusti niti naj nas ne zapusti,',
        58: 'da bo lahko naša srca nagnil k sebi, da hodimo po vseh njegovih poteh in da ohranjamo vse njegove zapovedi, njegove zakone in njegove sodbe, ki jih je zapovedal našim očetom.',
        59: 'Naj bodo te moje besede, s katerimi sem naredil ponižno prošnjo pred Gospodom, blizu Gospodu, našemu Bogu, podnevi in ponoči, da ohrani zadevo svojega služabnika in zadevo svojega ljudstva Izraela ob vseh časih, kakor bo stvar zahtevala,',
        60: 'da bo vse ljudstvo zemlje lahko vedelo, da Gospod je Bog in da tam ni nobenega drugega.',
        61: 'Naj bo vaše srce torej popolno z Gospodom, našim Bogom, da se ravna po njegovih zakonih in da ohranja njegove zapovedi, kakor je ta dan.«',
        62: 'Kralj in ves Izrael z njim je daroval klavno daritev pred Gospodom.',
        63: 'Salomon je daroval žrtvovanje mirovnih daritev, ki jih je daroval Gospodu, dvaindvajset tisoč volov in sto dvajset tisoč ovc. Tako so kralj in vsi Izraelovi otroci posvetili Gospodovo hišo.',
        64: 'Istega dne je kralj posvetil sredino dvora, ki je bila pred Gospodovo hišo, kajti tam je daroval žgalne daritve, jedilne daritve in tolščo mirovnih daritev, ker je bil bronast oltar, ki je bil pred Gospodom, premajhen, da sprejme žgalne daritve, jedilne daritve in tolščo mirovnih daritev.',
        65: 'Ob tistem času je Salomon priredil praznovanje in ves Izrael z njim, velika skupnost, od vhoda v Hamát do egiptovske reke, pred Gospodom, svojim Bogom, sedem dni in sedem dni, torej štirinajst dni.',
        66: 'Na osmi dan je ljudstvo odposlal proč in blagoslovili so kralja in radostni in veselega srca zaradi vse dobrote, ki jo je Gospod storil za svojega služabnika Davida in za svoje ljudstvo Izrael, odšli k svojim šotorom.',
    },
    9: {
        1: 'Pripetilo se je, ko je Salomon dokončal gradnjo Gospodove hiše, kraljeve hiše in vsega, kar je Salomon želel, kar mu je ugajalo storiti,',
        2: 'da se je Gospod drugič prikazal Salomonu, kakor se mu je prikazal pri Gibeónu.',
        3: 'Gospod mu je rekel: »Slišal sem tvojo molitev in tvojo ponižno prošnjo, ki si jo storil pred menoj. Jaz sem posvetil to hišo, ki si jo zgradil, da tja na veke postavim svoje ime in moje oči in moje srce bodo neprestano tam.',
        4: 'Če boš hodil pred menoj, kakor je hodil tvoj oče David, v neokrnjenosti srca in v poštenosti, da storiš glede na vse, kar sem ti zapovedal in da boš ohranjal moje zakone in moje sodbe,',
        5: 'potem bom na veke utrdil prestol tvojega kraljestva nad Izraelom, kakor sem obljubil tvojemu očetu Davidu, rekoč: ›Ne bo ti manjkal mož na Izraelovem prestolu.‹',
        6: 'Toda če se boste obrnili od sledenja meni, vi ali vaši otroci in ne boste ohranjali mojih zapovedi in mojih zakonov, ki sem jih postavil pred vas, temveč boste šli in služili drugim bogovom in jih oboževali,',
        7: 'potem bom Izraela odsekal iz dežele, ki sem jim jo dal in to hišo, ki sem jo posvetil za svoje ime, bom vrgel iz svojega pogleda in Izrael bo med vsemi ljudstvi pregovor in tarča posmeha.',
        8: 'In ob tej hiši, ki je visoka, bo vsak, kdor gre mimo nje, osupel in bo sikal. Rekli bodo: ›Zakaj je Gospod tako storil tej deželi in tej hiši?‹',
        9: 'Odgovorili bodo: ›Ker so zapustili Gospoda, svojega Boga, ki je njihove očete privedel ven iz egiptovske dežele in so se oprijeli drugih bogov, jih oboževali in jim služili, zato je Gospod nadnje privedel vse to zlo.‹',
        10: 'Pripetilo se je ob koncu dvajsetih let, ko je Salomon zgradil dve hiši, Gospodovo hišo in kraljevo hišo,',
        11: '(torej tirski kralj Hirám je Salomona opremil s cedrovim lesom, cipresovim lesom in z zlatom, glede na vso njegovo željo) da je nató kralj Salomon Hirámu dal dvajset mest v galilejski deželi.',
        12: 'Hirám je prišel iz Tira, da bi videl mesta, ki mu jih je Salomon dal. Le-ta pa mu niso ugajala.',
        13: 'Rekel je: »Kakšna so ta mesta, ki si mi jih dal, moj brat?« Imenoval jih je dežela Kabúl do tega dne.',
        14: 'Hirám je poslal h kralju sto dvajset talentov zlata.',
        15: 'In to je razlog dajatve obveznega dela, ki ga je dvignil kralj Salomon, da zgradi Gospodovo hišo, svojo lastno hišo, Miló, jeruzalemsko obzidje, Hacór, Megído in Gezer.',
        16: 'Kajti faraon, egiptovski kralj, je odšel gor, zavzel Gezer, ga požgal z ognjem in umoril Kánaance, ki so prebivali v mestu in ga dal za darilo svoji hčeri, Salomonovi ženi.',
        17: 'Salomon je zgradil Gezer, spodnji Bet Horón,',
        18: 'Baalát, Tadmór v divjini, v deželi',
        19: 'in vsa skladiščna mesta, ki jih je imel Salomon in mesta za njegove bojne vozove in mesta za njegove konjenike in to, kar je Salomon želel, da zgradi v Jeruzalemu, na Libanonu in po vsej deželi svojega gospostva.',
        20: 'Na vse ljudstvo, ki je preostalo od Amoréjcev, Hetejcev, Perizéjcev, Hivéjcev in Jebusejcev, ki niso bili od Izraelovih otrok,',
        21: 'na njihove otroke, ki so za njimi preostali v deželi, ki jih Izraelovi otroci niso mogli popolnoma uničiti, je Salomon naložil dajatev davka prisilnega dela do tega dne.',
        22: 'Toda izmed Izraelovih otrok Salomon ni naredil nobenega sužnja, temveč so bili bojevniki, njegovi služabniki, njegovi princi, njegovi poveljniki, vodje njegovih bojnih voz in njegovi konjeniki.',
        23: 'Ti so bili glavni častniki, ki so bili nad Salomonovim delom, petsto petdeset, ki so nadzorovali ljudstvo, ki je opravljalo delo.',
        24: 'Toda faraonova hči je prišla gor iz Davidovega mesta k svoji hiši, ki jo je Salomon zgradil zanjo. Potem je zgradil Miló.',
        25: 'Trikrat na leto je Salomon daroval žgalne daritve in mirovne daritve na oltarju, ki ga je zgradil Gospodu in zažgal je kadilo na oltarju, ki je bil pred Gospodom. Tako je dokončal hišo.',
        26: '§ Kralj Salomon je naredil floto ladij v Ecjón Geberju, ki je poleg Elota, na obali Rdečega morja, v edómski deželi.',
        27: 'Hirám je s Salomonovimi služabniki poslal v floto svoje služabnike, pomorščake, ki so imeli znanje o morju.',
        28: 'Prišli so do Ofírja in od tam vzeli zlato, štiristo dvajset talentov in to prinesli h kralju Salomonu.',
    },
    10: {
        1: 'Ko je kraljica iz Sabe slišala o Salomonovem slovesu glede Gospodovega imena, je prišla, da ga preizkusi s težkimi vprašanji.',
        2: 'Prišla je v Jeruzalem z zelo velikim spremstvom, s kamelami, ki so nosile dišave, zelo veliko zlata in [z] dragocenimi kamni. Ko je prišla k Salomonu, se je z njim posvetovala o vsem, kar je bilo na njenem srcu.',
        3: 'Salomon ji je povedal [odgovore na] vsa njena vprašanja. Ničesar ni bilo skritega pred kraljem, kar ji ne bi povedal.',
        4: 'Ko je kraljica iz Sabe videla vso Salomonovo modrost in hišo, ki jo je zgradil,',
        5: 'hrano njegove mize, sedenje njegovih služabnikov in položaj njegovih strežnikov, njihovo obleko, njegove dvorne točaje in njegovo vzpenjanje, s katerim je odšel gor h Gospodovi hiši, v njej ni bilo več duha.',
        6: 'Rekla je kralju: »Poročilo, ki sem ga slišala v svoji lastni deželi, o tvojih dejanjih in o tvoji modrosti, je bilo resnično.',
        7: 'Vendar nisem verjela besedam, dokler nisem prišla in so moje oči to videle. Glej, niti polovice mi niso povedali. Tvoja modrost in uspevanje presega sloves, ki sem ga slišala.',
        8: 'Srečni so tvoji možje, srečni so ti tvoji služabniki, ki nenehno stojijo pred teboj in ki slišijo tvojo modrost.',
        9: 'Blagoslovljen bodi Gospod, tvoj Bog, ki se je razveseljeval v tebi, da te je posadil na Izraelov prestol. Ker je Gospod na veke ljubil Izraela, zato te je postavil za kralja, da izvajaš sodbo in pravico.«',
        10: 'Kralju je izročila sto dvajset talentov zlata in od dišav zelo veliko zalogo in dragocene kamne. Tja ni prišlo več takšno obilje dišav kakor te, ki jih je kraljica iz Sabe dala kralju Salomonu.',
        11: 'Prav tako je Hirámova mornarica, ki je iz Ofírja pripeljala zlato, iz Ofírja pripeljala veliko obilje sandalovine in dragocenih kamnov.',
        12: 'Kralj je iz sandalovine naredil stebre za Gospodovo hišo in za kraljevo hišo, tudi harfe in plunke za pevce. Do tega dne tja ni prišlo nobene takšne sandalovine niti jih niso videli.',
        13: 'Kralj Salomon je kraljici iz Sabe izročil vse njene želje, karkoli je prosila, poleg tega, kar ji je Salomon dal od svoje kraljeve radodarnosti. Tako se je obrnila in odšla v svojo lastno deželo, ona in njeni služabniki.',
        14: 'Torej teža zlata, ki je v enem letu prišla k Salomonu, je bila šeststo šestinšestdeset talentov zlata,',
        15: 'poleg tega kar je imel od trgovcev, od preprodaje trgovcev z dišavami, od vseh kraljev iz Arabije in od voditeljev dežele.',
        16: 'Kralj Salomon je naredil dvesto okroglih ščitov iz kovanega zlata. Šeststo šeklov zlata je šlo k enemu okroglemu ščitu.',
        17: 'Naredil je tristo ščitov iz kovanega zlata. Tri funte zlata je šlo za en ščit. Kralj jih je postavil v hiši libanonskega gozda.',
        18: 'Poleg tega je kralj naredil velik prestol iz slonovine in ga prevlekel z najboljšim zlatom.',
        19: 'Prestol je imel šest stopnic in vrh prestola je bil zadaj okrogel. Na vsaki strani prestola sta bili naslonjali za roke in dva leva sta stala poleg naslonjal za roke.',
        20: 'Dvanajst levov je stalo na eni strani in na drugi, na šestih stopnicah. Kaj podobnega ni bilo narejenega v nobenem kraljestvu.',
        21: 'Vse Salomonove posode za pitje so bile iz zlata in vse posode hiše libanonskega gozda so bile iz čistega zlata, nobena ni bila iz srebra. V Salomonovih dneh le-to ni veljalo za nič.',
        22: 'Kajti kralj je imel na morju taršíško mornarico s Hirámovo mornarico. Enkrat na tri leta je prišla mornarica iz Taršíša noseč zlato, srebro, slonovino, opice in pave.',
        23: 'Tako je kralj Salomon zaradi bogastva in zaradi modrosti prekosil vse zemeljske kralje.',
        24: 'Vsa zemlja je iskala Salomona, da sliši njegovo modrost, ki jo je Bog položil v njegovo srce.',
        25: 'Vsak mož je prinesel svoje darilo, posode iz srebra, posode iz zlata, obleke, bojno opremo, dišave, konje, mule in to leto za letom.',
        26: 'Salomon je zbral skupaj bojne vozove in konjenike. Imel je tisoč štiristo bojnih voz in dvanajst tisoč konjenikov, ki jih je usmeril v mesta za bojne vozove in s kraljem v Jeruzalem.',
        27: 'Kralj je storil, da je bilo v Jeruzalemu zaradi obilja srebra kakor kamnov in storil, da je bilo ceder kakor egiptovskih smokev, ki so v dolini.',
        28: '§ Salomon je imel konje, privedene iz Egipta in laneno prejo. Kraljevi trgovci so laneno prejo prejeli za ceno.',
        29: 'Bojni voz je prišel gor in se iz Egipta pripeljal za šeststo šeklov srebra, konj pa [za] sto petdeset. Tako so jih za vse hetejske kralje in za sirske kralje privedli ven z njihovimi sredstvi.',
    },
    11: {
        1: 'Toda kralj Salomon je ljubil mnoge tuje žene, skupaj s faraonovo hčerjo, ženske iz Moába, Amónke, Edómke, Sidónke in Hetejke,',
        2: 'od narodov glede katerih je Gospod Izraelovim otrokom rekel: »Ne boste vstopili k njim niti oni ne smejo vstopiti k vam, kajti zagotovo bodo vaše srce odvrnili za svojimi bogovi.« Salomon se je v ljubezni trdno pridružil k njim.',
        3: 'Imel je sedemsto žená, princese in tristo priležnic in njegove žene so odvrnile njegovo srce.',
        4: 'Kajti zgodilo se je, ko je bil Salomon star, da so njegove žene njegovo srce odvrnile za drugimi bogovi in njegovo srce ni bilo popolno z Gospodom, njegovim Bogom, kot je bilo srce njegovega očeta Davida.',
        5: 'Kajti Salomon je šel za Astarto, boginjo Sidóncev in za Milkómom, gnusobo Amóncev.',
        6: 'Salomon je počel zlo v Gospodovih očeh in ni popolnoma šel za Gospodom, kakor je delal njegov oče David.',
        7: 'Potem je Salomon zgradil visok kraj za Kemoša, gnusobo Moábcev, na hribu, ki je pred Jeruzalemom in za Moloha, ogabnost Amónovih otrok.',
        8: 'Podobno je storil za vse svoje tuje žene, ki so zažigale kadilo in žrtvovale svojim bogovom.',
        9: 'Gospod pa je bil jezen nad Salomonom, ker je bilo njegovo srce odvrnjeno od Gospoda, Izraelovega Boga, ki se mu je dvakrat prikazal',
        10: 'in mu je glede te stvari zapovedal, da naj ne gre za drugimi bogovi. Toda tega, kar mu je Gospod zapovedal, ni ohranil.',
        11: 'Zato je Gospod Salomonu rekel: »Ker si to storil in nisi obvaroval moje zaveze in mojih zakonov, ki sem ti jih zapovedal, ti bom zagotovo iztrgal kraljestvo in ga dal tvojemu služabniku.',
        12: 'Vendar zaradi tvojega očeta Davida tega ne bom storil v tvojih dneh, temveč ga bom iztrgal iz roke tvojega sina.',
        13: 'Toda ne bom odtrgal vsega kraljestva, temveč bom en rod dal tvojemu sinu zaradi Davida, svojega služabnika in zaradi Jeruzalema, ki sem ga izbral.«',
        14: 'Gospod je Salomonu razvnel nasprotnika, Edómca Hadáda. Ta je bil iz kraljevega semena v Edómu.',
        15: 'Kajti pripetilo se je, ko je bil David v Edómu in je Joáb, poveljnik vojske, odšel gor, da pokoplje umorjene, potem ko je udaril vsakega moškega v Edómu',
        16: '(kajti šest mesecev je Joáb ostal tam z vsem Izraelom, dokler ni iztrebil vsakega moškega v Edómu),',
        17: 'da je Hadád pobegnil, on in z njim nekateri Edómci, služabniki njegovega očeta, da gredo v Egipt; Hadád je bil še majhen otrok.',
        18: 'Vstali so iz Midjána in prišli v Parán in s seboj so vzeli može iz Parána ter prišli v Egipt, k faraonu, egiptovskemu kralju, ki mu je dal hišo, mu določil živež in mu dal deželo.',
        19: 'Hadád je našel veliko naklonjenost v faraonovih očeh, tako da mu je dal za ženo sestro svoje lastne žene, sestro kraljice Tahpenése.',
        20: 'Tahpenésina sestra mu je rodila Genubáta, njegovega sina, ki ga je Tahpenésa vzgajala v faraonovi hiši in Genubát je bil v faraonovi hiši med faraonovimi sinovi.',
        21: 'Ko je Hadád v Egiptu slišal, da je David zaspal s svojimi očeti in da je bil Joáb, poveljnik vojske, mrtev, je Hadád rekel faraonu: »Pusti me oditi, da lahko grem k svoji lastni deželi.«',
        22: 'Potem mu je faraon rekel: »Toda kaj ti je manjkalo z menoj, glej, da si prizadevaš, da greš v svojo lastno deželo?« Odgovoril je: »Nič, vendar me vseeno pusti oditi.«',
        23: 'Bog pa mu je razvnel drugega nasprotnika, Eljadájevega sina Rezóna, ki je pobegnil pred svojim gospodom Hadadézerjem, kraljem iz Cobe.',
        24: 'K sebi je zbral može in postal poveljnik nad četo, ko je David usmrtil tiste iz Cobe in odšli so v Damask, tam prebivali in kraljevali v Damasku.',
        25: 'Vse Salomonove dni je bil nasprotnik Izraelu, poleg vragolije, ki jo je storil Hadád. Preziral je Izrael in kraljeval nad Sirijo.',
        26: 'Jerobeám, Nebátov sin, Efratejec iz Ceréde, Salomonov služabnik (katerega materino ime je bilo Cerúja, vdova), celo on je dvignil svojo roko zoper kralja.',
        27: 'To je bil razlog, da je svojo roko dvignil zoper kralja. Salomon je zgradil Miló in popravil vrzeli mesta svojega očeta Davida.',
        28: 'Mož Jerobeám je bil mogočen, hraber človek in Salomon, ko je videl, da je bil mladenič podjeten, ga je postavil za vladarja nad vso zadolžitvijo Jožefove hiše.',
        29: 'Pripetilo se je ob tistem času, ko je Jerobeám odšel iz Jeruzalema, da ga je na poti našel prerok Šilčan Ahíja, in ta se je odel z novo obleko in onadva sta bila sama na polju.',
        30: 'Ahíja je zgrabil novo obleko, ki je bila na njem in jo raztrgal na dvanajst kosov',
        31: 'in rekel Jerobeámu: »Vzemi si deset kosov, kajti tako govori Gospod, Izraelov Bog: ›Glej, iztrgal bom kraljestvo iz Salomonove roke in tebi bom dal deset rodov',
        32: '(toda on bo imel en rod zaradi mojega služabnika Davida in zaradi Jeruzalema, mesta, ki sem ga izbral izmed vseh Izraelovih rodov),',
        33: 'zato ker so me zapustili in oboževali Astarto, boginjo Sidóncev, Kemoša, boga Moábcev in Milkóma, boga Amónovih otrok in niso hodili po mojih poteh, da delajo to, kar je pravilno v mojih očeh in da ohranjajo moje zakone in moje sodbe, kakor je počel njegov oče David.',
        34: 'Vendar iz njegove roke ne bom vzel celotnega kraljestva, temveč ga bom zaradi Davida, svojega služabnika, ki sem ga izbral, naredil za princa vse dni njegovega življenja, ker je ohranjal moje zapovedi in moje zakone,',
        35: 'toda kraljestvo bom vzel iz roke njegovega sina in ga dal tebi, celó deset rodov.',
        36: 'Njegovemu sinu pa bom dal en rod, da bo David, moj služabnik, lahko vedno imel luč pred menoj v Jeruzalemu, mestu, ki sem ga izbral, da tam postavim svoje ime.',
        37: 'Vzel te bom in kraljeval boš glede na vse, kar želi tvoja duša in boš kralj nad Izraelom.',
        38: 'Zgodilo se bo, če boš prisluhnil vsemu, kar ti zapovem in boš hodil po mojih poteh in delal to, kar je pravilno v mojih očeh, da se držiš mojih zakonov in mojih zapovedi, kakor se je moj služabnik David, da bom jaz s teboj in ti bom zgradil zanesljivo hišo, kakor sem jo zgradil za Davida, Izraela pa bom izročil tebi.',
        39: 'Zaradi tega bom prizadel Davidovo seme, toda ne na veke.‹«',
        40: 'Salomon je torej iskal, da ubije Jerobeáma. Jerobeám pa je vstal in pobegnil v Egipt, k egiptovskemu kralju Šišáku in v Egiptu je bil do Salomonove smrti.',
        41: 'Ostala Salomonova dela in vse, kar je storil in njegova modrost, mar niso zapisana v knjigi Salomonovih del.',
        42: 'Časa, ko je Salomon v Jeruzalemu kraljeval nad vsem Izraelom, je bilo štirideset let.',
        43: 'Salomon je zaspal s svojimi očeti in bil pokopan v mestu svojega očeta Davida. Namesto njega je zakraljeval njegov sin Rehabám.',
    },
    12: {
        1: 'Rehabám je odšel v Sihem, kajti ves Izrael je prišel v Sihem, da ga postavijo za kralja.',
        2: 'Pripetilo se je, ko je Nebátov sin Jerobeám, ki je bil še v Egiptu, slišal o tem (kajti pobegnil je izpred prisotnosti kralja Salomona in je Jerobeám prebival v Egiptu),',
        3: 'da so poslali in ga poklicali. Jerobeám in vsa Izraelova skupnost pa je prišla in spregovorila Rehabámu, rekoč:',
        4: '»Tvoj oče je naš jarem naredil boleč. Sedaj torej olajšaj bolečo službo svojega očeta in njegov težek jarem, ki ga je položil na nas in mi ti bomo služili.«',
        5: 'Rekel jim je: »Odidite še za tri dni, potem ponovno pridite k meni.« In ljudstvo je odšlo.',
        6: 'Kralj Rehabám se je posvetoval s starci, ki so stali pred njegovim očetom Salomonom, medtem ko je še živel in rekel: »Kako svetujete, da lahko odgovorim temu ljudstvu?«',
        7: 'Odgovorili so mu, rekoč: »Če hočeš biti ta dan služabnik temu ljudstvu in jim hočeš služiti in jim odgovoriti in jim govoriti dobre besede, potem bodo tvoji služabniki na veke.«',
        8: 'Toda zapustil je nasvet starcev, ki so mu ga dali in se posvetoval z mladeniči, ki so odrasli z njim in ki so stali pred njim',
        9: 'in jim rekel: »Kakšen nasvet dajete vi, da lahko odgovorimo temu ljudstvu, ki mi je govorilo, rekoč: ›Naredi jarem, ki ga je tvoj oče položil nad nas, lažji?‹«',
        10: 'Mladeniči, ki so zrasli z njim, so mu govorili, rekoč: »Tako boš govoril temu ljudstvu, ki ti je govorilo, rekoč: ›Tvoj oče je naš jarem naredil težek, toda ti nam ga olajšaj;‹ tako jim boš rekel: ›Moj mali prst bo debelejši kakor očetova ledja.',
        11: 'Kakor vam je moj oče naložil težek jarem, bom sedaj dodal vašemu jarmu. Moj oče vas je kaznoval z biči, toda jaz vas bom kaznoval s škorpijoni.‹«',
        12: 'Tako je Jerobeám in vse ljudstvo tretji dan prišlo k Rehabámu, kakor je kralj določil, rekoč: »Ponovno pridite k meni tretji dan.«',
        13: 'Kralj je ljudstvu surovo odgovoril in zapustil nasvet starcev, ki so mu ga dali.',
        14: 'Spregovoril jim je glede na nasvet mladeničev, rekoč: »Moj oče je vaš jarem naredil težek, jaz pa bom vašemu jarmu dodal. Moj oče vas je kaznoval tudi z biči, toda jaz vas bom kaznoval s škorpijoni.«',
        15: 'Zatorej kralj ni prisluhnil ljudstvu, kajti stvar je bila od Gospoda, da je lahko izpolnil svojo besedo, ki jo je Gospod po Šilčanu Ahíju govoril Nebátovemu sinu Jerobeámu.',
        16: 'Torej ko je ves Izrael videl, da jim kralj ni prisluhnil, je ljudstvo odgovorilo kralju, rekoč: »Kakšen delež imamo v Davidu? Niti nimamo dediščine v Jesejevem sinu. K svojim šotorom, oh Izrael. Sedaj poglej k svoji lastni hiši, David.« Tako je Izrael odšel v svoje šotore.',
        17: 'Toda kar se tiče Izraelovih otrok, ki so prebivali v Judovih mestih, je nad njimi kraljeval Rehabám.',
        18: 'Potem je kralj Rehabám poslal Adoráma, ki je bil nad davkom in ves Izrael ga je kamnal s kamni, da je umrl. Zato je kralj Rehabám pohitel, da se spravi k svojemu bojnemu vozu, da pobegne v Jeruzalem.',
        19: 'Tako se je Izrael uprl zoper Davidovo hišo do današnjega dne.',
        20: 'Pripetilo se je, ko je ves Izrael slišal, da je Jerobeám ponovno prišel, da so poslali in ga poklicali k skupnosti in ga postavili za kralja nad vsem Izraelom. Tam ni bilo nikogar, ki je sledil Davidovi hiši, razen samo Judovega rodu.',
        21: 'Ko je Rehabám prišel v Jeruzalem, je zbral vso Judovo hišo, z Benjaminovim rodom, sto osemdeset tisoč izbranih mož, ki so bili bojevniki, da se bojujejo zoper Izraelovo hišo, da kraljestvo ponovno privedejo k Salomonovemu sinu Rehabámu.',
        22: 'Toda beseda od Boga je prišla k Šemajáju, Božjemu možu, rekoč:',
        23: '»Govori Salomonovemu sinu Rehabámu, Judovemu kralju in vsej Judovi in Benjaminovi hiši in preostanku ljudstva, rekoč:',
        24: '›Tako govori Gospod: ›Ne boste šli gor niti se ne boste borili zoper vaše brate, Izraelove otroke. Vsak mož naj se vrne k svoji hiši, kajti ta stvar je od mene.‹« Prisluhnili so torej Gospodovi besedi in se vrnili, da odidejo, glede na Gospodovo besedo.',
        25: 'Potem je Jerobeám na gori Efrájim zgradil Sihem in tam prebival in odšel od tam ter zgradil Penuél.',
        26: 'Jerobeám je v svojem srcu rekel: »Sedaj se bo kraljestvo vrnilo k Davidovi hiši.',
        27: 'Če gre to ljudstvo gor, da opravi klavno daritev v Gospodovi hiši, v Jeruzalemu, potem se bo srce tega ljudstva ponovno obrnilo k njihovemu gospodu, k Judovemu kralju Rehabámu, mene pa bodo ubili in ponovno odšli k Judovemu kralju Rehabámu.«',
        28: 'Nakar se je kralj posvetoval in naredil dve teleti iz zlata ter jim rekel: »To je za vas preveč, da greste gor v Jeruzalem. Poglejte svoje bogove, oh Izrael, ki so te privedli gor iz egiptovske dežele.«',
        29: 'Eno je postavil v Betelu, drugo pa v Danu.',
        30: 'Ta stvar je postala greh, kajti ljudstvo je odšlo, da bi oboževalo pred enim, celó k Danu.',
        31: 'Naredil je hišo visokih krajev in iz najnižjih izmed ljudstva naredil duhovnike, ki niso bili izmed Lévijevih sinov.',
        32: 'Jerobeám je odredil praznovanje v osmem mesecu, na petnajsti dan meseca, podobno prazniku, ki je v Judu in daroval na oltarju. Tako je storil v Betelu, žrtvoval je teletoma, ki ju je naredil in v Betelu je postavil duhovnike visokih krajev, ki jih je naredil.',
        33: 'Tako je daroval na oltarju, ki ga je naredil v Betelu, na petnajsti dan osmega meseca, celó v mesecu, ki ga je zasnoval iz svojega lastnega srca in odredil praznovanje Izraelovim otrokom in daroval na oltarju in zažgal kadilo.',
    },
    13: {
        1: 'Glej, iz Juda je prišel Božji mož po Gospodovi besedi do Betela in Jerobeám je stal pri oltarju, da zažge kadilo.',
        2: 'Zaklical je zoper oltar v Gospodovi besedi in rekel: »Oh oltar, oltar, tako govori Gospod: ›Glej, otrok bo rojen Davidovi hiši, po imenu Jošíja in na tebi bo daroval duhovnike visokih krajev, ki zažigajo kadilo na tebi in človeške kosti bodo žgane na tebi.‹«',
        3: 'In isti dan je dal znamenje, rekoč: »To je znamenje, ki ga je Gospod govoril: ›Glej, oltar bo razpočen in pepel, ki je na njem, se bo izsul.‹«',
        4: 'Pripetilo se je, da ko je kralj Jerobeám slišal izjavo Božjega moža, ki je zaklical proti oltarju v Betelu, da je svojo roko iztegnil od oltarja, rekoč: »Primite ga.« Njegova roka, ki jo je iztegnil proti njemu, pa se je posušila, tako da je ni mogel povleči nazaj k sebi.',
        5: 'Tudi oltar je bil razpočen in pepel razsut z oltarja, glede na znamenje, ki ga je Božji mož dal po Gospodovi besedi.',
        6: 'Kralj je Božjemu možu odgovoril in rekel: »Prosi sedaj obličje Gospoda, svojega Boga in moli zame, da bo moja roka lahko ponovno povrnjena k meni.« Božji mož je rotil Gospoda in kraljeva roka je bila ponovno povrnjena k njemu in postala, kakor je bila ta poprej.',
        7: 'Kralj je Božjemu možu rekel: »Pridi z menoj domov, osveži se in dal ti bom nagrado.«',
        8: 'Božji mož je kralju odgovoril: »Če mi daš polovico svoje hiše, ne bom šel s teboj niti na tem kraju ne bom jedel kruha niti pil vode.«',
        9: 'Kajti tako mi je bilo naročeno po Gospodovi besedi, rekoč: »Ne jej kruha, niti ne pij vode, niti se ne obračaj ponovno po isti poti, po kateri si prišel.«',
        10: 'Tako je odšel po drugi poti in se ni vrnil po poti, po kateri je prišel v Betel.',
        11: 'Torej v Betelu je prebival star prerok. Njegovi sinovi so prišli in mu povedali vsa dela, ki jih je tisti dan Božji mož storil v Betelu. Tudi besede, ki jih je govoril kralju, so povedali svojemu očetu.',
        12: 'Njihov oče jim je rekel: »Po kateri poti je odšel?« Kajti njegovi sinovi so videli po kateri poti je odšel Božji mož, ki je prišel iz Juda.',
        13: 'Svojim sinovom je rekel: »Osedlajte mi osla.« Tako so mu osedlali osla, in jahal je na njem',
        14: 'in odšel za Božjim možem in ga našel sedeti pod hrastom. Rekel mu je: » Ali si ti Božji mož, ki je prišel iz Juda?« Ta je rekel: »Jaz sem.«',
        15: 'Potem mu je rekel: »Pridi z menoj domov in jej kruh.«',
        16: 'Ta pa je rekel: »Ne smem se vrniti s teboj, niti vstopiti s teboj, niti na tem kraju ne bom jedel kruha niti pil vode,',
        17: 'kajti po Gospodovi besedi mi je bilo rečeno: ›Ti tam ne boš jedel niti kruha niti pil vode niti se ne boš ponovno obrnil, da bi šel po poti, po kateri si prišel.‹«',
        18: 'Rekel mu je: »Tudi jaz sem prerok, kot si ti in angel mi je po Gospodovi besedi govoril, rekoč: ›Privedi ga s seboj nazaj v svojo hišo, da bo lahko jedel kruh in pil vodo.‹« Toda lagal mu je.',
        19: 'Tako je z njim odšel nazaj in v njegovi hiši jedel kruh in pil vodo.',
        20: 'Pripetilo se je, ko sta sedela pri mizi, da je Gospodova beseda prišla preroku, ki ga je privedel nazaj',
        21: 'in Božjemu možu, ki je prišel iz Juda, je zaklical, rekoč: »Tako govori Gospod: ›Ker nisi ubogal Gospodovih ust in se nisi držal Gospodove zapovedi, ki ti jo je Gospod, tvoj Bog, zapovedal,',
        22: 'temveč si prišel nazaj in si na tem kraju jedel kruh in pil vodo, o čemer ti je Gospod rekel: ›Ne jej kruha in ne pij nobene vode,‹ tvoje truplo ne bo prišlo v mavzolej tvojih očetov.‹«',
        23: 'Pripetilo se je, ko je pojedel kruh in potem ko je popil, da je zanj osedlal osla, namreč za preroka, ki ga je privedel nazaj.',
        24: 'Ko je ta odšel, ga je na poti srečal lev in ga usmrtil. Njegovo truplo je bilo vrženo na pot in poleg njega je stal osel, [in] tudi lev je stal poleg trupla.',
        25: 'Glej, ljudje so hodili mimo in videli truplo, vrženo na pot in leva, stoječega poleg trupla in prišli so in to povedali v mestu, kjer je živel stari prerok.',
        26: 'Ko je prerok, ki ga je privedel nazaj iz poti, slišal o tem, je rekel: »To je Božji mož, ki je bil neposlušen Gospodovi besedi. Zato ga je Gospod izročil levu, ki ga je raztrgal in umoril glede na Gospodovo besedo, ki mu jo je govoril.«',
        27: 'Svojim sinovom je spregovoril, rekoč: »Osedlajte mi osla.« In osedlali so mu.',
        28: 'Odšel je in na poti našel njegovo truplo ter osla in leva stati poleg trupla. Lev ni pojedel trupla niti raztrgal osla.',
        29: 'Prerok je pobral truplo Božjega moža, ga položil na osla in ga privedel nazaj, in stari prerok je prišel v mesto, da žaluje in da ga pokoplje.',
        30: 'Njegovo truplo je položil v svoj grob in žalovali so nad njim, rekoč: »Ojoj, moj brat!«',
        31: 'Pripetilo se je, potem ko ga je pokopal, da je govoril svojim sinovom, rekoč: »Ko umrem, potem me pokopljite v mavzoleju, v katerem je pokopan Božji mož. Moje kosti položite poleg njegovih kosti,',
        32: 'kajti beseda, ki jo je klical po Gospodovi besedi zoper oltar v Betelu in zoper vse hiše visokih krajev, ki so v mestih Samarije, se bo zagotovo zgodila.«',
        33: 'Po tej stvari se Jerobeám ni odvrnil iz svoje zle poti, temveč je ponovno naredil najnižje izmed ljudi za duhovnike na visokih krajih. Kogarkoli je hotel, je uméstil in ta je postal eden izmed duhovnikov visokih krajev.',
        34: 'Ta stvar je postala greh Jerobeámovi hiši, celo, da jo odseka in da jo uniči iz obličja zemlje.',
    },
    14: {
        1: 'Ob tistem času je Jerobeámov sin Abíja zbolel.',
        2: 'Jerobeám je rekel svoji ženi: »Vstani, prosim te in se preobleci, da te ne bodo spoznali, da si Jerobeámova žena in pojdi v Šilo. Glej, tam je prerok Ahíja, ki mi je povedal, da naj bi bil jaz kralj nad tem ljudstvom.',
        3: 'S seboj vzemi deset hlebov, kolačke in vrč medu in pojdi k njemu. Povedal ti bo, kaj bo z otrokom.«',
        4: 'Jerobeámova žena je tako storila, vstala, odšla v Šilo in prišla k Ahijevi hiši. Toda Ahíja je ni mogel videti, kajti njegove oči so zaradi starosti otemnele.',
        5: 'Gospod je rekel Ahiju: »Glej, prihaja Jerobeámova žena, da od tebe prosi stvar za svojega sina, kajti on je bolan. Tako in tako ji boš rekel, kajti tako bo, ko bo vstopila, da se bo pretvarjala, da je druga ženska.«',
        6: 'To je bilo tako, da ko je Ahíja zaslišal glas njenih stopal, ko je vstopila pri vratih, je rekel: »Vstopi, ti Jerobeámova žena; zakaj se pretvarjaš, da si druga? Kajti k tebi sem poslan s težkimi novicami.',
        7: 'Pojdi, povej Jerobeámu: ›Tako govori Gospod, Izraelov Bog: ›Ker sem te povišal izmed ljudstva in te naredil princa nad svojim ljudstvom Izraelom',
        8: 'in kraljestvo odtrgal od Davidove hiše in ga dal tebi; pa vendar ti nisi bil kakor moj služabnik David, ki je ohranjal moje zapovedi in ki mi je sledil z vsem svojim srcem, da počne samo to, kar je bilo pravilno v mojih očeh,',
        9: 'temveč si storil zlo bolj kot vsi, ki so bili pred teboj, kajti odšel si in si naredil druge bogove in ulite podobe, da me dražiš do jeze in si me vrgel za svoj hrbet.',
        10: 'Zato glej, jaz bom nad Jerobeámovo hišo privedel zlo in od Jerobeáma bom iztrebil tistega, ki lula proti zidu in tistega, ki je zaprt in je ostal v Izraelu in odvzel bom preostanek Jerobeámove hiše, kakor človek odvaža gnoj, dokler ta ves ne izgine.',
        11: 'Tistega, ki bo od Jerobeámovih umrl v mestu, bodo žrli psi. Tistega pa, ki umre na polju, bo žrla perjad neba, kajti Gospod je to govoril.',
        12: 'Vstani torej, pojdi k svoji lastni hiši in ko tvoja stopala vstopijo v mesto, bo otrok umrl.',
        13: 'Ves Izrael bo žaloval za njim in ga pokopal, kajti on bo edini izmed Jerobeámovih prišel do groba, ker se je v Jerobeámovi hiši v njem našla neka dobra stvar do Gospoda, Izraelovega Boga.',
        14: 'Poleg tega si bo Gospod dvignil kralja nad Izraelom, ki bo tisti dan iztrebil Jerobeámovo hišo. Toda kaj? Celo sedaj.',
        15: 'Kajti Gospod bo udaril Izraela, kakor se trst maje v vodi in Izraela bo izkoreninil iz te dobre dežele, ki jo je dal njihovim očetom in razkropil jih bo preko reke, ker so si naredili svoje ašere, izzivajoč Gospoda do jeze.',
        16: 'Izraela se bo odrekel zaradi grehov Jerobeáma, ki je storil greh in ki je Izraela pripravil, da greši.‹«',
        17: 'Jerobeámova žena je vstala, odšla in prišla v Tirco in ko je prišla k pragu vrat, je otrok umrl',
        18: 'in pokopali so ga in ves Izrael je žaloval za njim, glede na Gospodovo besedo, ki jo je govoril po roki svojega služabnika, preroka Ahíja.',
        19: 'Ostala Jerobeámova dela, kako se je vojskoval in kako je kraljeval, glej, ta so zapisana v kroniški knjigi Izraelovih kraljev.',
        20: 'Dni, ko je Jerobeám kraljeval, je bilo dvaindvajset let in zaspal je s svojimi očeti in namesto njega je zakraljeval njegov sin Nadáb.',
        21: 'Salomonov sin Rehabám je kraljeval v Judu. Rehabám je bil star enainštirideset let, ko je začel kraljevati in v Jeruzalemu je kraljeval sedemnajst let, mestu, ki ga je Gospod izbral izmed vseh Izraelovih rodov, da tam postavi svoje ime. Ime njegove matere je bilo Amónka Naáma.',
        22: 'Juda je počel zlo v Gospodovih očeh in s svojimi grehi, ki so jih zagrešili, so ga dražili do ljubosumnosti, nad vsem, kar so počeli njihovi očetje.',
        23: 'Kajti zgradili so si tudi visoke kraje, podobe in ašere na vsakem visokem hribu in pod vsakim zelenim drevesom.',
        24: 'V deželi so bili tudi posvečeni vlačugarji in ti so počeli glede na vse ogabnosti narodov, ki jih je Gospod pregnal pred Izraelovimi otroki.',
        25: 'Pripetilo se je v petem letu kralja Rehabáma, da je egiptovski kralj Šišák prišel gor nad Jeruzalem.',
        26: 'Odnesel je zaklade Gospodove hiše in zaklade kraljeve hiše, celo vse je odnesel. Odnesel je vse zlate ščite, ki jih je Salomon naredil.',
        27: 'Kralj Rehabám je namesto njih naredil bronaste ščite in jih predal v roke vodje straže, ki je varoval vrata kraljeve hiše.',
        28: 'To je bilo tako, kadar je kralj odšel v Gospodovo hišo, da jih je straža nosila in jih [potem] ponovno odnesla v stražarnico.',
        29: 'Torej preostala izmed Rehabámovih dejanj in vse, kar je storil, mar niso zapisana v kroniški knjigi Judovih kraljev?',
        30: 'Med Rehabámom in Jerobeámom pa je bila vse njune dni vojna.',
        31: 'Rehabám je zaspal s svojimi očeti in bil s svojimi očeti pokopan v Davidovem mestu. Ime njegove matere je bilo Amónka Naáma. Namesto njega je zakraljeval njegov sin Abíjam.',
    },
    15: {
        1: 'Torej v osemnajstem letu kralja Jerobeáma, Nebátovega sina, je nad Judom zakraljeval Abíjam.',
        2: 'Tri leta je kraljeval v Jeruzalemu. Ime njegove matere je bilo Maáha, Abišalómova hči.',
        3: 'Hodil je v vseh grehih svojega očeta, ki jih je ta storil pred njim in njegovo srce ni bilo popolno z Gospodom, njegovim Bogom, kakor je bilo srce njegovega očeta Davida.',
        4: 'Kljub temu mu je zaradi Davida Gospod, njegov Bog, dal svetilko v Jeruzalemu, da za seboj postavi svojega sina in da vzpostavi Jeruzalem,',
        5: 'ker je David delal to, kar je bilo prav v Gospodovih očeh in se vse dni svojega življenja ni obrnil stran od katerekoli stvari, ki mu jo je zapovedal, razen samo v zadevi Hetejca Urijája.',
        6: 'Med Rehabámom in Jerobeámom pa je bila vojna vse dni njegovega življenja.',
        7: 'Torej preostala izmed Abíjamovih dejanj in vse, kar je storil, mar niso zapisana v kroniški knjigi Judovih kraljev? In bila je vojna med Abíjamom in Jerobeámom.',
        8: 'Abíjam je zaspal s svojimi očeti in pokopali so ga v Davidovem mestu. Namesto njega je zakraljeval njegov sin Asá.',
        9: 'V dvajsetem letu Izraelovega kralja Jerobeáma, je nad Judom zakraljeval Asá.',
        10: 'V Jeruzalemu je kraljeval enainštirideset let. Ime njegove matere je bilo Maáha, Abišalómova hči.',
        11: 'Asá je delal to, kar je bilo pravilno v Gospodovih očeh, kakor je delal njegov oče David.',
        12: 'Iz dežele je odpravil posvečene vlačugarje in odstranil vse malike, ki so jih naredili njegovi očetje.',
        13: 'Tudi svojo mater Maáho, celo njo je odstranil, da bi bila kraljica, ker si je v ašeri naredila malika. Asá je uničil njenega malika in ga zažgal pri potoku Kidronu.',
        14: 'Toda visokih krajev ni odstranil. Kljub temu je bilo Asájevo srce, vse dni njegovega življenja, popolno z Gospodom.',
        15: 'V Gospodovo hišo je prinesel stvari, ki jih je njegov oče posvetil in stvari, ki jih je sam posvetil, srebro, zlato in posode.',
        16: 'Med Asájem in Izraelovim kraljem Bašájem pa je bila vse njune dni vojna.',
        17: 'Izraelov kralj Bašá je odšel gor zoper Juda in zgradil Ramo, da Judovemu kralju Asáju ne bi pustil iti ven ali priti noter.',
        18: 'Potem je Asá vzel vse srebro in zlato, ki je ostalo v zakladnicah Gospodove hiše in zakladnicah kraljeve hiše in jih izročil v roko svojih služabnikov. Kralj Asá pa jih je poslal k Ben Hadádu, Tabrimónovemu sinu, Hezjónovemu sinu, kralju Sirije, ki je prebival pri Damasku, rekoč:',
        19: '»Zaveza je med menoj in teboj in med mojim očetom in tvojim očetom. Glej, k tebi sem poslal dar iz srebra in zlata. Pridi in prelomi svojo zavezo z Izraelovim kraljem Bašájem, da bo lahko odšel od mene.«',
        20: 'Tako je Ben Hadád prisluhnil kralju Asáju in poslal poveljnike vojsk, ki jih je imel, zoper Izraelova mesta in udaril Ijón, Dan, Abél Bet Maáho in ves Kinéret, z vso Neftálijevo deželo.',
        21: 'Pripetilo se je, ko je Bašá slišal o tem, da je prenehal z gradnjo Rame in prebival v Tirci.',
        22: 'Potem je kralj Asá po vsej Judeji naredil razglas. Nihče ni bil izvzet. Vzeli so kamne iz Rame in les, s katerim je Bašá gradil in kralj Asá je z njim gradil Gebo Benjamin in Micpo.',
        23: 'Preostala izmed vseh Asájevih dejanj in vsa njegova moč in vse, kar je storil in mesta, ki jih je zgradil, mar niso zapisana v kroniški knjigi Judovih kraljev? Kljub temu je bil v času svoje visoke starosti bolan na svojih stopalih.',
        24: 'Asá je zaspal s svojimi očeti in s svojimi očeti je bil pokopan v mestu svojega očeta Davida. Namesto njega je zakraljeval njegov sin Józafat.',
        25: 'Jerobeámov sin Nadáb je začel kraljevati nad Izraelom v drugem letu Judovega kralja Asája in nad Izraelom je kraljeval dve leti.',
        26: 'Počel je zlo v Gospodovih očeh in hodil po poti svojega očeta in v njegovem grehu, s katerim je Izraela primoral, da greši.',
        27: 'Zoper njega se je zarotil Ahíjev sin Bašá iz Isahárjeve hiše in Bašá ga ja udaril pri Gibetónu, ki pripada Filistejcem, kajti Nadáb in ves Izrael sta oblegala Gibetón.',
        28: 'Celo v tretjem letu Judovega kralja Asája ga je Bašá ubil in zakraljeval namesto njega.',
        29: 'Pripetilo se je, ko je zakraljeval, da je udaril vso Jerobeámovo hišo. Jerobeámu ni pustil nikogar, ki diha, dokler ga ni pokončal, glede na Gospodovo izjavo, ki jo je govoril po svojem služabniku, Šilčanu Ahíju,',
        30: 'zaradi Jerobeámovih grehov, ki jih je ta zagrešil in ki so Izraela pripravili grešiti s svojim izzivanjem, s katerim so Gospoda, Izraelovega Boga, izzivali do jeze.',
        31: 'Torej preostala izmed Nadábovih dejanj in vse, kar je storil, mar niso zapisana v kroniški knjigi Izraelovih kraljev?',
        32: 'Med Asájem in Izraelovim kraljem Bašájem je bila vse njune dni vojna.',
        33: 'V tretjem letu Judovega kralja Asája je nad Izraelom v Tirci začel kraljevati Ahíjev sin Bašá, štiriindvajset let.',
        34: 'Počel je zlo v Gospodovih očeh in hodil po Jerobeámovi poti in v njegovem grehu, s katerim je Izraela primoral, da greši.',
    },
    16: {
        1: 'Potem je Gospodova beseda prišla Hananíjevemu sinu Jehúju zoper Bašája, rekoč:',
        2: '»Ker kakor sem te povišal iz prahu in te naredil princa nad mojim ljudstvom Izraelom in si hodil po Jerobeámovi poti in primoral moje ljudstvo Izraela, da greši, da me z njihovimi grehi dražiš do jeze,',
        3: 'glej, bom odvzel potomstvo Bašája in potomstvo njegove hiše in tvojo hišo bom naredil podobno hiši Nebátovega sina Jerobeáma.',
        4: 'Tistega, ki od Bašája umre v mestu, bo jedel pes, tistega pa, ki od njegovih umre na poljih, bo žrla perjad neba.«',
        5: 'Torej preostala izmed Bašájevih del in vse, kar je storil in njegova moč, mar niso zapisana v kroniški knjigi Izraelovih kraljev?',
        6: 'Tako je Bašá zaspal s svojimi očeti in je bil pokopan v Tirci. Namesto njega je zakraljeval njegov sin Elá.',
        7: 'Prav tako je po roki Hananíjevega sina Jehúja prišla Gospodova beseda zoper Bašája in zoper njegovo hišo, celo za vse zlo, ki ga je storil v Gospodovih očeh, v draženju do jeze z deli njegovih rok, ker je bil podoben Jerobeámovi hiši in ker ga je ubil.',
        8: 'V šestindvajsetem letu Judovega kralja Asája, je nad Izraelom v Tirci [za] dve leti začel kraljevati Bašájev sin Elá.',
        9: 'Njegov služabnik Zimrí, poveljnik polovice njegovih bojnih vozov, se je zoper njega zarotil, medtem ko je bil ta v Tirci in se do pijanosti napil v hiši Arcája, oskrbnika njegove hiše v Tirci.',
        10: 'Zimrí je vstopil, ga udaril in ubil v sedemindvajsetem letu Judovega kralja Asája in zakraljeval namesto njega.',
        11: 'Ko je začel kraljevati, se je pripetilo, da je takoj, ko je sedel na svoj prestol, usmrtil vso Bašájevo hišo. Ni mu pustil niti enega, ki lula proti zidu niti od njegove žlahte niti od njegovih prijateljev.',
        12: 'Tako je Zimrí uničil vso Bašájevo hišo glede na Gospodovo besedo, ki jo je govoril zoper Bašája po preroku Jehúju,',
        13: 'zaradi vseh Bašájevih grehov in grehov njegovega sina Elája, s katerimi sta grešila in s katerimi sta Izraela pripravila, da greši v draženju Gospoda, Izraelovega Boga, do jeze s svojimi ničevostmi.',
        14: 'Torej preostala izmed Elájevih dejanj in vse, kar je storil, mar niso zapisana v kroniški knjigi Izraelovih kraljev?',
        15: 'V sedemindvajsetem letu Judovega kralja Asája je Zimrí sedem dni kraljeval v Tirci. Ljudstvo pa je bilo utaborjeno zoper Gibetón, ki je pripadal Filistejcem.',
        16: 'Ljudstvo, ki je bilo utaborjeno, je slišalo reči: »Zimrí je koval zaroto in tudi umoril kralja.« Zato je ves Izrael ta dan v taboru postavil Omrija, poveljnika vojske, [za] kralja nad Izraelom.',
        17: 'Omri se je dvignil iz Gibetóna in ves Izrael z njim in oblegali so Tirco.',
        18: 'Pripetilo se je, ko je Zimrí videl, da je bilo mesto zavzeto, da je odšel v palačo kraljeve hiše in kraljevo hišo nad seboj zažgal z ognjem in umrl',
        19: 'zaradi svojih grehov, ki jih je zagrešil v početju zla v Gospodovih očeh, s hojo po Jerobeámovi poti in v svojem grehu, ki ga je storil, da je Izraela pripravil, da greši.',
        20: 'Torej preostala izmed Zimríjevih del in njegova izdaja, ki jo je storil, mar niso zapisana v kroniški knjigi Izraelovih kraljev?',
        21: 'Potem je bilo Izraelovo ljudstvo razdeljeno na dva dela. Polovica ljudstva je sledila Ginátovemu sinu Tibníju, da ga postavi za kralja, polovica pa je sledila Omriju.',
        22: 'Toda ljudstvo, ki je sledilo Omriju, je prevladalo zoper ljudstvo, ki je sledilo Ginátovemu sinu Tibníju. Tako je Tibní umrl, Omri pa zakraljeval.',
        23: 'V enaintridesetem letu Judovega kralja Asája je nad Izraelom začel kraljevati Omri, dvanajst let. Šest let je kraljeval v Tirci.',
        24: 'Od Šemerja je za dvajset talentov srebra kupil hrib Samarijo in gradil na hribu in ime mesta, ki ga je zgradil, je poimenoval Samarija, po Šemerjevemu imenu, lastniku hriba.',
        25: 'Toda Omri je počel zlo v Gospodovih očeh in počel huje kakor vsi, ki so bili pred njim.',
        26: 'Kajti hodil je po vsej poti Nebátovega sina Jerobeáma in v njegovem grehu, s katerim je Izraela pripravil, da greši, da s svojimi ničevostmi do jeze draži Gospoda, Izraelovega Boga.',
        27: 'Torej preostala izmed Omrijevih dejanj, ki jih je storil in njegova moč, ki jo je pokazal, mar niso zapisana v kroniški knjigi Izraelovih kraljev?',
        28: 'Tako je Omri zaspal s svojimi očeti in bil pokopan v Samariji. Namesto njega je zakraljeval njegov sin Aháb.',
        29: 'V osemintridesetem letu Judovega kralja Asája je nad Izraelom začel kraljevati Omrijev sin Aháb in Omrijev sin Aháb je nad Izraelom v Samariji kraljeval dvaindvajset let.',
        30: 'Omrijev sin Aháb je počel zlo v Gospodovih očeh, bolj kakor vsi, ki so bili pred njim.',
        31: 'Pripetilo se je, kakor če je bila to zanj lahka stvar, da hodi v grehih Nebátovega sina Jerobeáma, da je za ženo vzel Jezabelo, hčer Etbáala, kralja Sidóncev in odšel, služil Báalu in ga oboževal.',
        32: 'V Báalovi hiši je postavil oltar za Báala, ki ga je zgradil v Samariji.',
        33: 'Aháb je naredil ašero in Aháb je storil več kakor vsi Izraelovi kralji, ki so bili pred njim, da draži k jezi Gospoda, Izraelovega Boga.',
        34: 'V njegovih dneh je Hiél Betelčan zidal Jeriho. Njen temelj je položil v svojem prvorojencu Abirámu in njena velika vrata je postavil v svojem najmlajšem sinu Segúbu, glede na besedo od Gospoda, ki jo je spregovoril po Nunovemu sinu Józuetu.',
    },
    17: {
        1: 'Tišbéjec Elija, ki je bil izmed prebivalcev Gileáda, je rekel Ahábu: » Kakor živi Gospod, Izraelov Bog, pred katerim stojim, tukaj ta leta ne bo niti rose niti dežja, razen glede na mojo besedo.«',
        2: 'Gospodova beseda je prišla k njemu, rekoč:',
        3: '»Pojdi od tod in se obrni proti vzhodu in se skrij pri potoku Kerítu, ki je pred Jordanom.',
        4: 'Zgodilo se bo, da boš pil iz potoka, krokarjem pa sem zapovedal, da te tam hranijo.«',
        5: 'Tako je odšel in storil glede na Gospodovo besedo, kajti odšel je in prebival pri potoku Kerítu, ki je pred Jordanom.',
        6: 'Krokarji so mu prinašali kruh in meso zjutraj ter kruh in meso zvečer, pil pa je iz potoka.',
        7: 'Čez nekaj časa se je pripetilo, da je potok usahnil, ker v deželi ni bilo dežja.',
        8: 'K njemu je prišla beseda od Gospoda, rekoč:',
        9: '»Vstani, pojdi v Zarepto, ki pripada Sidónu in prebivaj tam. Glej, tamkajšnji vdovi sem zapovedal, da te podpira.«',
        10: 'Tako je vstal in odšel v Zarepto. Ko je prišel k velikim vratom mesta, glej, je bila tam ženska vdova, ki je nabirala veje. Zaklical je k njej ter ji rekel: »Prinesi mi, prosim te, malo vode v posodi, da lahko pijem.«',
        11: 'Ko je šla, da bi to prinesla, je zaklical k njej in rekel: »Prinesi mi, prosim te, grižljaj kruha v svoji roki.«',
        12: 'Rekla je: » Kakor Gospod, tvoj Bog, živi, nimam kolača, temveč prgišče moke v sodčku in malo olja v vrču in glej, nabiram dve palici, da lahko grem in to pripravim zase in za svojega sina, da bova to lahko pojedla in umrla.«',
        13: 'Elija ji je rekel: »Ne boj se. Pojdi in stôri, kakor si rekla. Toda od tega najprej meni naredi majhen kolač in mi ga prinesi, potem pa naredi zase in za svojega sina.',
        14: 'Kajti tako govori Gospod, Izraelov Bog: ›Sodček z moko ne bo pošel niti v vrču ne bo zmanjkalo olja do dneva, ko Gospod pošlje dež na zemljo.‹«',
        15: 'Odšla je in storila glede na Elijevo izjavo. Ona, on in njena hiša so jedli mnogo dni.',
        16: 'In sodček z moko ni pošel niti olja v vrču ni zmanjkalo, glede na Gospodovo besedo, ki jo je govoril po Eliju.',
        17: 'Po teh stvareh se je pripetilo, da se je sin ženske, gospodarice hiše, počutil bolnega, in njegova slabost je bila tako huda, da v njem ni ostalo nobenega diha.',
        18: 'Eliju je rekla: »Kaj imam s teboj, oh ti Božji mož? Ali si prišel k meni, da mi prikličeš moj greh v spomin in da ubiješ mojega sina?«',
        19: 'Rekel ji je: »Daj mi svojega sina.« Vzel ga je iz njenega naročja in ga odnesel gor na podstrešje, kjer je prebival in ga položil na svojo lastno posteljo.',
        20: 'Klical je h Gospodu in rekel: »Oh Gospod, moj Bog, mar si zlo privedel tudi nad to vdovo, pri kateri se mudim, s pokončanjem njenega sina?«',
        21: 'Trikrat se je raztegnil nad otrokom, klical h Gospodu in rekel: »Oh Gospod, moj Bog, prosim te, naj se duša tega otroka ponovno vrne vanj.«',
        22: 'Gospod je uslišal Elijev glas in otrokova duša se je ponovno vrnila vanj in je oživel.',
        23: 'Elija je vzel otroka, ga privedel dol iz sobe v hišo in ga izročil njegovi materi. Elija je rekel: »Poglej, tvoj sin živi.«',
        24: 'Ženska je rekla Eliju: »Po tem sedaj vem, da si Božji mož in da je Gospodova beseda v tvojih ustih resnična.«',
    },
    18: {
        1: 'Po mnogih dneh se je pripetilo, da je Gospodova beseda prišla k Eliju v tretjem letu, rekoč: »Pojdi, pokaži se Ahábu in jaz bom na zemljo poslal dež.«',
        2: 'Elija je odšel, da se pokaže Ahábu. Tam v Samariji pa je bila huda lakota.',
        3: 'Aháb je poklical Obadjá, ki je bil voditelj njegove hiše. (Torej Obadjá se je silno bal Gospoda.',
        4: 'Kajti to je bilo tako, ko je Jezabela iztrebila Gospodove preroke, da je Obadjá vzel sto prerokov in jih po petdeset skril v votlino in jih hranil s kruhom in vodo.)',
        5: 'Aháb je rekel Obadjáju: »Pojdi v deželo, k vodnim studencem in k vsem potokom. Morda bomo lahko našli travo, da rešimo konje in mule žive, da ne izgubimo vseh živali.«',
        6: 'Tako sta si razdelila deželo, da gresta skoznjo. Aháb je sam odšel eno pot, Obadjá pa je odšel drugo pot.',
        7: 'Ko je bil Obadjá na poti, glej, ga je srečal Elija. Ta ga je spoznal in padel na svoj obraz ter rekel: » Ali si ti, moj gospod Elija?«',
        8: 'Odgovoril mu je: »Jaz sem. Pojdi, povej svojemu gospodarju: ›Glej, Elija je tukaj.‹«',
        9: 'Rekel je: »Kaj sem grešil, da hočeš svojega služabnika izročiti v Ahábovo roko, da me ubije?',
        10: 'Kakor živi Gospod, tvoj Bog, ni ne naroda ne kraljestva, kamor moj gospodar ni poslal, da te poiščejo. In ko so rekli: › Njega ni tukaj,‹ je od kraljestva in naroda vzel prisego, da te niso našli.',
        11: 'In sedaj praviš: ›Pojdi, povej svojemu gospodarju: ›Glej, Elija je tukaj.‹‹',
        12: 'Takoj, ko odidem od tebe, se bo zgodilo, da te bo Gospodov Duh odnesel ne vem kam. Ko pridem in povem Ahábu in te ne bo mogel najti, bo tako, da me bo ubil. Vendar se jaz, tvoj služabnik, od svoje mladosti bojim Gospoda.',
        13: 'Mar ni bilo povedano mojemu gospodu kaj sem storil, ko je Jezabela usmrtila Gospodove preroke, kako sem skril sto mož, Gospodovih prerokov, po petdeset v votlino in jih hranil s kruhom in vodo?',
        14: 'Sedaj pa praviš: ›Pojdi, povej svojemu gospodarju: ›Glej, Elija je tukaj ‹ in me bo ubil.«',
        15: 'Elija je rekel: » Kakor živi Gospod nad bojevniki, pred katerim stojim, se mu bom danes zagotovo pokazal.«',
        16: 'Tako je Obadjá odšel, da sreča Ahába in povedal mu je. Aháb je odšel, da sreča Elija.',
        17: 'Pripetilo se je, ko je Aháb zagledal Elija, da mu je Aháb rekel: » Si ti ta, ki nadleguje Izraela?«',
        18: 'In ta je odgovoril: »Nisem jaz nadlegoval Izraela, temveč ti in hiša tvojega očeta v tem, da ste zapustili Gospodove zapovedi, ti pa si sledil Báalom.',
        19: 'Zdaj torej pošlji in zberi k meni ves Izrael na goro Karmel in štiristo petdeset Báalovih prerokov in štiristo Ašerinih prerokov, ki jedo za Jezabelino mizo.«',
        20: 'Tako je Aháb poslal k vsem Izraelovim otrokom in preroke skupaj zbral h gori Karmel.',
        21: 'Elija je prišel k vsemu ljudstvu in rekel: »Doklej omahujete med dvema možnostma? Če Gospod je Bog, sledite njemu, toda če je Báal, potem sledite njemu.« Ljudstvo pa mu ni odgovorilo niti besede.',
        22: 'Potem je Elija rekel ljudstvu: »Jaz, celó samo jaz sem ostal Gospodov prerok, toda Báalovih prerokov je štiristo petdeset mož.',
        23: 'Naj nam torej dajo dva bikca in naj si enega bikca izberejo zase, ga razrežejo na koščke in ga položijo na les in pod njim ne podtaknejo ognja, jaz pa bom pripravil drugega bikca in ga položil na les in pod njim ne podtaknem ognja.',
        24: 'Kličite k imenu svojih bogov, jaz pa bom klical h Gospodovemu imenu. Bog, ki odgovarja z ognjem, naj bo on Bog.« Vse ljudstvo je odgovorilo in reklo: »To je dobro rečeno.«',
        25: '§ Elija je Báalovim prerokom rekel: »Izberite si enega bikca zase in tega pripravite najprej, kajti vas je mnogo, in kličite ime svojih bogov, toda spodaj ne podnetite ognja.«',
        26: 'Vzeli so bikca, ki jim je bil dan in ga pripravili in od jutra do poldneva klicali k Báalovemu imenu, rekoč: »Oh Báal, usliši nas.« Toda ni bilo nobenega glasu niti nikogar, da bi odgovoril. In poskakovali so na oltarju, ki je bil narejen.',
        27: 'Pripetilo se je opoldan, da jih je Elija zasmehoval in rekel: »Glasno vpijte, kajti on je bog; ali klepeta ali zalezuje ali je na potovanju ali morda spi in mora biti prebujen.«',
        28: 'Glasno so vpili in se po svoji navadi rezali z noži in nožiči, dokler ni po njih lila kri.',
        29: 'Pripetilo se je, ko je sredina dneva minila in so prerokovali do časa darovanja večerne daritve, da tam ni bilo, niti glasu niti odgovora, niti nikogar, ki bi upošteval.',
        30: 'Elija je rekel vsemu ljudstvu: »Pridite bliže k meni.« In vse ljudstvo je prišlo bliže k njemu. Popravil je Gospodov oltar, ki je bil razrušen.',
        31: 'Elija je vzel dvanajst kamnov, glede na število rodov Jakobovih sinov, ki mu je prišla Gospodova beseda, rekoč: »Izrael bo tvoje ime.«',
        32: 'S kamni je v Gospodovem imenu zgradil oltar, in okoli oltarja naredil jarek, tako velik, da bi lahko vseboval dve meri semen.',
        33: 'Les je postavil v red in bikca razsekal na koščke, ga položil na les in rekel: »Napolnite štiri sodčke z vodo in jih izlijte na žgalno daritev in na les.«',
        34: 'Rekel je: » To storite drugič.« In to so storili drugič. Rekel je: » To storite tretjič.« In to so storili tretjič.',
        35: 'Voda je tekla naokoli oltarja in tudi jarek je napolnil z vodo.',
        36: 'Ob času darovanja večerne daritve se je pripetilo, da se je približal prerok Elija in rekel: » Gospod, Bog Abrahama, Izaka in Izraela, naj bo to znano ta dan, da si ti Bog v Izraelu in da sem jaz tvoj služabnik in da sem vse te stvari storil na tvojo besedo.',
        37: 'Prisluhni mi, oh Gospod, prisluhni mi, da bo to ljudstvo lahko vedelo, da si ti Gospod Bog in da si ti njihova srca ponovno obrnil nazaj.«',
        38: 'Potem je padel Gospodov ogenj in použil žgalno daritev, les, kamne, prah in polizal vodo, ki je bila v jarku.',
        39: 'Ko je vse ljudstvo to videlo, so padli na svoje obraze in rekli: » Gospod, on je Bog; Gospod, on je Bog.«',
        40: 'Elija jim je rekel: »Primite Báalove preroke, naj nobeden izmed njih ne pobegne.« Prijeli so jih in Elija jih je odvedel dol k potoku Kišónu in jih tam usmrtil.',
        41: 'Elija je rekel Ahábu: »Vstani, jej in pij, kajti tam je zvok obilja dežja.«',
        42: 'Tako je Aháb odšel gor, da jé in da pije. Elija pa je odšel gor, na vrh Karmela in se vrgel dol na zemljo in svoj obraz dal med svoja kolena',
        43: 'in svojemu služabniku rekel: »Pojdi sedaj gor, glej proti morju.« In ta je odšel gor, pogledal in rekel: » Tam ni nič.« Rekel je: »Pojdi ponovno, sedemkrat.«',
        44: 'Pripetilo se je sedmič, da je rekel: »Glej, tam vstaja iz morja majhen oblak, podoben človeški roki.« Rekel je: »Pojdi gor in reci Ahábu: ›Pripravi svoj bojni voz in se spusti dol, da te ne ustavi dež.‹«',
        45: 'V vmesnem času se je pripetilo, da je bilo nebo črno z oblaki in vetrom in tam je bil velik dež. Aháb je jahal in šel v Jezreél.',
        46: 'Gospodova roka pa je bila na Eliju. Opasal je svoja ledja in pred Ahábom tekel k vhodu v Jezreél.',
    },
    19: {
        1: 'Aháb je Jezabeli povedal vse, kar je storil Elija in poleg tega, kako je z mečem umoril vse preroke.',
        2: 'Potem je Jezabela k Eliju poslala poslanca, rekoč: »Tako naj mi storijo bogovi in tudi več, če ne bom jutri okrog tega časa naredila tvojega življenja kakor življenja enega izmed teh.«',
        3: 'Ko je to videl, je vstal in hodil za svoje življenje in prišel v Beeršébo, ki pripada Judu in tam pustil svojega služabnika.',
        4: 'Toda on sam je odšel pot enega dne v divjino in prišel ter se usedel pod brinovo drevo. In zase je zahteval, da bi lahko umrl in rekel: »Dovolj je. Sedaj, oh Gospod, vzemi moje življenje, kajti nisem boljši kakor moji očetje.«',
        5: 'Ko se je ulegel in pod brinovim drevesom zaspal, glej, takrat se ga je dotaknil angel in mu rekel: »Vstani in jej.«',
        6: 'Pogledal je in glej, tam je bil kolač, pečen na ogorkih in vrč vode pri njegovi glavi. Jedel je in pil ter ponovno legel.',
        7: 'Gospodov angel je ponovno prišel, drugič, se ga dotaknil in rekel: »Vstani in jej, kajti potovanje je preveliko zate.«',
        8: 'Vstal je, jedel, pil in hodil v moči te hrane štirideset dni in štirideset noči do Božje gore Horeb.',
        9: 'In prišel tja v votlino ter tam prenočil. Glej, k njemu je prišla beseda od Gospoda in on mu je rekel: »Kaj delaš tukaj, Elija?«',
        10: 'Rekel je: »Bil sem zelo goreč za Gospoda, Boga nad bojevniki, kajti Izraelovi otroci so zapustili tvojo zavezo, zrušili tvoje oltarje in z mečem pomorili tvoje preroke, in jaz, celó samo jaz sem ostal in strežejo mi po življenju, da bi mi ga vzeli.«',
        11: 'In on je rekel: »Pojdi naprej in stoj na gori pred Gospodom.« Glej, Gospod je šel mimo in velik, močan veter je trgal gore in skale drobil na koščke pred Gospodom, toda Gospoda ni bilo v vetru. In za vetrom potres, toda Gospoda ni bilo v potresu.',
        12: 'In za potresom ogenj, toda Gospod ni bil v ognju. In za ognjem tih, majhen glas.',
        13: 'Bilo je tako, ko je Elija to slišal, da je svoj obraz zavil v svoje ogrinjalo in odšel ven in stal na vhodu votline. Glej, tam je prišel k njemu glas in rekel: »Kaj delaš tukaj, Elija?«',
        14: 'Rekel je: »Bil sem zelo goreč za Gospoda, Boga nad bojevniki, ker so Izraelovi otroci zapustili tvojo zavezo, zrušili tvoje oltarje in z mečem pomorili tvoje preroke. Jaz, celó samo jaz sem ostal in strežejo mi po življenju, da bi mi ga vzeli.«',
        15: 'Gospod mu je rekel: »Pojdi, vrni se po svoji poti k divjini Damaska in ko prideš, mazili Hazaéla, da postane kralj nad Sirijo.',
        16: 'Nimšíjevega sina Jehúja pa boš mazilil, da bo kralj nad Izraelom. Šafátovega sina Elizeja, iz Abél Mehóle, pa boš mazili, da bo prerok namesto tebe.',
        17: 'Zgodilo se bo, da tisti, ki pobegne Hazaélovemu meču, ga bo ubil Jehú. Tistega, ki pobegne pred Jehújevim mečem, pa bo ubil Elizej.',
        18: 'Vendar sem si jih pustil v Izraelu sedem tisoč, vsa kolena, ki se niso upognila Báalu in vsaka usta, ki ga niso poljubila.«',
        19: 'Tako je odpotoval od tam in našel Šafátovega sina Elizeja, ki je oral z dvanajstimi volovskimi jarmi pred seboj in on je bil z dvanajstim. Elija je šel mimo njega in svoje ogrinjalo vrgel nanj.',
        20: 'Ta je pustil vole in stekel za Elijem ter rekel: »Pusti me, prosim te, poljubiti svojega očeta in svojo mater in potem ti bom sledil.« Rekel mu je: »Pojdi ponovno nazaj, kajti kaj sem ti storil?«',
        21: 'Vrnil se je nazaj od njega, vzel volovski jarem, jih usmrtil in njihovo meso skuhal z volovskimi pripravami in dal ljudstvu in so jedli. Potem je vstal, odšel za Elijem in mu služil.',
    },
    20: {
        1: 'Sirski kralj Ben Hadád je zbral skupaj vso svojo vojsko, in tam je bilo z njim dvaintrideset kraljev, konji in bojni vozovi. Odšel je gor, oblegal Samarijo in se vojskoval zoper njo.',
        2: 'V mesto je poslal poslance, k Izraelovemu kralju Ahábu in mu rekel: »Tako govori Ben Hadád:',
        3: '›Tvoje srebro in tvoje zlato je moje. Tudi tvoje žene in tvoji otroci, celó najčednejši, so moji.‹«',
        4: 'Izraelov kralj je odgovoril in rekel: »Moj gospod, oh kralj, glede na tvoj govor: ›Jaz sem tvoj in vse kar imam.‹«',
        5: 'Poslanci so ponovno prišli in rekli: »Tako govori Ben Hadád, rekoč: ›Čeprav sem poslal k tebi, rekoč: ›Izročil mi boš svoje srebro, svoje zlato, svoje žene in svoje otroke,',
        6: 'bom vendar naslednji dan, okrog tega časa, k tebi poslal svoje služabnike in preiskali bodo tvojo hišo in hiše tvojih služabnikov, in zgodilo se bo, da karkoli je prijetno v tvojih očeh, da bodo to položili v svojo roko in to odnesli proč.‹«',
        7: 'Potem je Izraelov kralj poklical vse starešine dežele in rekel: »Spoznajte, prosim vas in poglejte, kako ta mož išče vragolijo, kajti k meni je poslal po moje žene, po moje otroke, po moje srebro in po moje zlato, pa mu nisem odrekel.«',
        8: 'Vse starešine in vse ljudstvo mu je reklo: »Ne prisluhni mu niti ne privoli.«',
        9: 'Zatorej je Ben Hadádovim poslancem rekel: »Mojemu gospodu kralju povejte: ›Vse, po kar si prvič poslal k svojemu služabniku, bom storil, toda te stvari ne morem storiti.‹« Poslanci so odšli in mu ponovno prinesli besedo.',
        10: 'Ben Hadád je poslal k njemu in rekel: »Bogovi naj mi tako storijo in še več, če bo prah Samarije zadoščal za prgišča vsega ljudstva, ki mi sledi.«',
        11: 'Izraelov kralj je odgovoril in rekel: »Povej mu: ›Naj se tisti, ki si opasuje opremo, ne baha kakor, da jo je že odložil.‹«',
        12: 'Pripetilo se je, ko je Ben Hadád slišal to sporočilo, medtem ko je pil on in kralji v paviljonih, da je rekel svojim služabnikom: »Postrojite se v vrsto.« In postavili so se v vrsto zoper mesto.',
        13: 'Glej, tam je h kralju Ahábu prišel prerok iz Izraela, rekoč: »Tako govori Gospod: ›Ali si videl vso to veliko množico? Glej, ta dan jo bom izročil v tvojo roko, in ti boš vedel, da sem jaz Gospod.‹«',
        14: 'Aháb je rekel: »Po kom?« Rekel je: »Tako govori Gospod: › Celó po mladeničih princev provinc.‹« Potem je rekel: »Kdo bo ukazoval bitki?« Odgovoril je: »Ti.«',
        15: 'Potem je preštel mladeniče princev provinc in bilo jih je dvesto dvaintrideset. Za njimi je preštel vse ljudstvo, celo vse Izraelove otroke, bilo [jih je] sedem tisoč.',
        16: 'Ven so odšli opoldan. Toda Ben Hadád se je v paviljonih opijal do pijanosti, on in kralji, dvaintrideset kraljev, ki so mu pomagali.',
        17: 'Mladeniči princev provinc so prvi odšli ven in Ben Hadád je poslal ven in povedali so mu, rekoč: »Tam so prišli možje iz Samarije.«',
        18: 'Rekel je: »Če so prišli ven za mir, jih ujemite žive, ali če so prišli ven za vojno, jih ujemite žive.«',
        19: 'Tako so ti mladeniči princev provinc prišli ven iz mesta in vojska, ki jim je sledila.',
        20: 'Usmrtili so vsak svojega moža in Sirci so zbežali, Izrael pa jih je zasledoval in sirski kralj Ben Hadád je s konjeniki pobegnil na konju.',
        21: 'Izraelov kralj je odšel ven in udaril konje in vozove in Sirce usmrtil z velikim pokolom.',
        22: 'Prerok je prišel k Izraelovemu kralju in mu rekel: »Pojdi, okrepi se in se ozri in poglej kaj počneš, kajti ob vrnitvi leta bo kralj iz Sirije ponovno prišel gor zoper tebe.«',
        23: 'Služabniki kralja iz Sirije so mu rekli: »Njihovi bogovi so bogovi hribov, zato so bili močnejši kakor mi, toda naj se borimo zoper njih na ravnini in bomo zagotovo močnejši kakor oni.',
        24: 'Stôri to stvar. Kralje vzemi proč, vsakega moža iz svojega kraja in namesto njih postavi poveljnike.',
        25: 'Naštej si vojsko, podobno vojski, ki si jo izgubil, konja za konja in bojni voz za bojni voz, in mi se bomo borili zoper njih na ravnini in bomo zagotovo močnejši kakor oni.« Prisluhnil je njihovemu glasu in tako storil.',
        26: 'Pripetilo se je ob vrnitvi leta, da je Ben Hadád preštel Sirce in odšel gor v Afék, da se bori zoper Izrael.',
        27: 'Izraelovi otroci so bili prešteti in so bili vsi prisotni in odšli zoper njih. Izraelovi otroci so se utaborili pred njimi kakor dva majhna tropa kozličkov, toda Sirci so napolnili deželo.',
        28: 'Prišel je Božji mož in spregovoril Izraelovemu kralju ter rekel: »Tako govori Gospod: ›Ker so Sirci rekli: › Gospod je Bog hribov, toda on ni Bog dolin, zato bom vso to veliko množico izročil v tvojo roko in spoznali boste, da jaz sem Gospod.‹«',
        29: 'Sedem dni so taborili eden nasproti drugemu. In bilo je tako, da so se na sedmi dan spoprijeli in Izraelovi otroci so v enem dnevu izmed Sircev usmrtili sto tisoč pešcev.',
        30: 'Toda ostali so pobegnili v Afék, v mesto in tam je obzidje padlo na sedemindvajset tisoč mož, ki so ostali. Ben Hadád pa je pobegnil in prišel v mesto, v notranjo sobo.',
        31: 'Njegovi služabniki so mu rekli: »Glej sedaj, slišali smo, da so kralji Izraelove hiše usmiljeni kralji. Pusti nam, prosimo te, da opašemo vrečevino okoli svojih ledij in vrvi na svoje glave in pojdimo ven k Izraelovemu kralju. Morda bo rešil tvoje življenje.«',
        32: 'Tako so na svoja ledja opasali vrečevino, na svoje glave položili vrvi in prišli k Izraelovemu kralju ter rekli: »Tvoj služabnik Ben Hadád govori: ›Prosim te, pusti me živega.‹« Rekel je: »Je še živ? On je moj brat.«',
        33: 'Torej možje so marljivo opazovali ali bo katerakoli stvar prišla od njega in jo hitro zgrabili ter rekli: »Tvoj brat Ben Hadád.« Potem je rekel: »Pojdite, privedite ga.« Potem je Ben Hadád prišel naravnost k njemu in dal mu je, da je prišel gor v bojni voz.',
        34: 'Ben Hadád mu je rekel: »Mesta, ki jih je moj oče vzel od tvojega očeta, bom povrnil in zase si boš naredil ulice v Damasku, kakor jih je moj oče naredil v Samariji.« Potem je Aháb rekel: »S to zavezo te bom poslal proč.« Tako je z njim sklenil zavezo in ga poslal proč.',
        35: 'Nek mož, izmed preroških sinov, je rekel svojemu bližnjemu po Gospodovi besedi: »Udari me, prosim te.« Človek pa je odklonil, da bi ga udaril.',
        36: 'Potem mu je rekel: »Ker nisi ubogal Gospodovega glasu, glej, te bo takoj, ko odideš od mene, ubil lev.« In takoj, ko je odšel od njega, ga je našel lev in ga usmrtil.',
        37: 'Potem je našel drugega moža in rekel: »Udari me, prosim te.« Mož ga je udaril, tako da ga je pri udarjanju ranil.',
        38: 'Tako je prerok odšel in ob poti čakal na kralja in se preoblekel, s pepelom na svojem obrazu.',
        39: 'Ko je kralj šel mimo, je ta vpil h kralju in rekel: »Tvoj služabnik je odšel ven v sredo bitke in glej, mož se je obrnil vstran in mi privedel moža ter rekel: ›Varuj tega moža. Če bo na kakršenkoli način ta izginil, potem bo tvoje življenje za njegovo življenje ali pa boš plačal talent srebra.‹',
        40: 'Medtem ko je bil tvoj služabnik zaposlen tukaj in tam, je oni odšel.« Izraelov kralj mu je rekel: »Takšna bo tvoja sodba; ti si jo odločil.«',
        41: '§ Pohitel je in si iz svojega obraza obrisal pepel in Izraelov kralj ga je prepoznal, da je bil izmed prerokov.',
        42: 'In ta mu je rekel: »Tako govori Gospod: ›Ker si iz svoje roke izpustil moža, ki sem ga določil za popolno uničenje, zato bo šlo tvoje življenje za njegovo življenje in tvoje ljudstvo za njegovo ljudstvo.‹«',
        43: 'Izraelov kralj je odšel k svoji hiši hud in nezadovoljen ter prišel v Samarijo.',
    },
    21: {
        1: 'Po teh stvareh se je pripetilo, da je imel Jezreélec Nabót vinograd, ki je bil v Jezreélu, čisto pri palači samarijskega kralja Ahába.',
        2: 'Aháb je spregovoril Nabótu, rekoč: »Daj mi svoj vinograd, da ga bom lahko imel za zeliščni vrt, ker je ta čisto pri moji hiši, jaz pa ti bom zanj dal boljši vinograd, kakor je ta. Ali pa, če se ti zdi dobro, ti bom dal njegovo vrednost v denarju.«',
        3: 'Nabót je rekel Ahábu: » Gospod me obvaruj, da bi ti dal dediščino svojih očetov.«',
        4: 'Aháb je prišel v svojo hišo zlovoljen in jezen, zaradi besede, ki mu jo je govoril Jezreélec Nabót, kajti rekel je: »Ne bom ti dal dediščine svojih očetov.« Ulegel se je na svojo posteljo in svoj obraz obrnil stran in ni hotel jesti kruha.',
        5: 'Toda njegova žena Jezabela je prišla k njemu in mu rekla: »Zakaj je tvoj duh tako žalosten, da ne ješ kruha?«',
        6: 'Rekel ji je: »Ker sem govoril Jezreélcu Nabótu in mu rekel: ›Daj mi svoj vinograd za denar. Ali, če ti ugaja, ti bom zanj dal drug vinograd. Pa je odgovoril: ›Ne bom ti dal svojega vinograda.‹«',
        7: 'Njegova žena Jezabela mu je rekla: »Mar ne vladaš sedaj ti Izraelovemu kraljestvu? Vstani in jej kruh in naj bo tvoje srce veselo. Jaz ti bom dala vinograd Jezreélca Nabóta.«',
        8: 'Tako je v Ahábovem imenu napisala pisma in jih zapečatila z njegovim pečatom in pisma poslala k starešinam in k plemičem, ki so bili v njenem mestu in prebivali z Nabótom.',
        9: 'V pismih je napisala, rekoč: »Razglasite post in Nabóta postavite visoko med ljudstvo.',
        10: 'Predenj postavite dva moža, Beliálova sinova, da pričujeta zoper njega, rekoč: ›Preklinjal si Boga in kralja.‹ Potem ga odvedite ven in ga kamnajte, da bo lahko umrl.«',
        11: 'Ljudje iz njegovega mesta, torej starešine in plemiči, ki so bili prebivalci v njegovem mestu, so storili, kakor jim je poslala Jezabela in kakor je bilo to zapisano v pismih, ki jih je poslala k njim.',
        12: 'Razglasili so post in Nabóta postavili na visoko med ljudstvom.',
        13: 'Vstopila sta dva moža, Beliálova otroka in se usedla pred njim. Beliálova moža sta v prisotnosti ljudstva pričevala zoper njega, torej zoper Nabóta, rekoč: »Nabót je preklinjal Boga in kralja.« Potem so ga odvedli ven iz mesta in kamnali s kamni, da je ta umrl.',
        14: 'Potem so poslali k Jezabeli, rekoč: »Nabót je kamnan in je mrtev.«',
        15: 'Pripetilo se je, ko je Jezabela slišala, da je bil Nabót kamnan in je bil mrtev, da je Jezabela rekla Ahábu: »Vstani, vzemi posest vinograda Jezreélca Nabóta, ki ti jo je odklonil dati za denar, kajti Nabót ni živ, temveč mrtev.«',
        16: 'Ko je Aháb slišal, da je bil Nabót mrtev, se je pripetilo, da je Aháb vstal, da gre dol v vinograd Jezreélca Nabóta, da ga vzame v last.',
        17: 'Gospodova beseda je prišla Tišbéjcu Eliju, rekoč:',
        18: '»Vstani, pojdi dol, da srečaš Izraelovega kralja Ahába, ki je v Samariji. Glej, on je v Nabótovem vinogradu, kamor je odšel dol, da ga vzame v last.',
        19: '§ Spregovoril mu boš, rekoč: ›Tako govori Gospod: ›Ali si ubil in tudi vzel v last?‹ Spregovoril mu boš, rekoč: ›Tako govori Gospod: ›Na kraju, kjer so psi lizali Nabótovo kri, bodo psi lizali tvojo kri, celo tvojo.‹«',
        20: 'Aháb je rekel Eliju: »Ali si me našel, oh moj sovražnik?« Ta je odgovoril: »Našel sem te, ker si se prodal, da počneš zlo v Gospodovih očeh.',
        21: 'Glej, nadte bom privedel zlo in ti odvedel tvoje potomstvo in od Ahába bom iztrebil karkoli, kar lula proti zidu in tistega, ki je zaprt in je ostal v Izraelu,',
        22: 'in tvojo hišo bom naredil podobno hiši Nebátovega sina Jerobeáma in podobno hiši Ahíjevega sina Bašája, zaradi izzivanja, s katerim ste me dražili do jeze in Izraela pripravili, da greši.«',
        23: '§ Gospod je spregovoril tudi o Jezabeli, rekoč: »Psi bodo žrli Jezabelo pri jezreélskem zidu.',
        24: 'Kdor od Ahába umre v mestu, ga bodo žrli psi. Tistega, ki umre na polju, pa bo žrla perjad neba.',
        25: 'Toda nikogar ni bilo podobnega Ahábu, ki bi se prodal, da počne zlobnost v Gospodovih očeh, katerega je razvnela njegova žena Jezabela.',
        26: 'Zelo gnusno je počel v sledenju malikom, glede na vse stvari, kakor so storili Amoréjci, ki jih je Gospod pregnal pred Izraelovimi otroki.«',
        27: 'Ko je Aháb slišal te besede, se je pripetilo, da je pretrgal svoja oblačila in si na svoje meso nadel vrečevino, se postil, ležal v vrečevini in tiho hodil.',
        28: 'Gospodova beseda je prišla k Tišbéjcu Eliju, rekoč:',
        29: '»Ali vidiš, kako se je Aháb ponižal pred menoj? Ker se ponižuje pred menoj, zla ne bom privedel v njegovih dneh, temveč bom v dneh njegovega sina nad njegovo hišo privedel zlo.«',
    },
    22: {
        1: 'Tri leta so nadaljevali brez vojne med Sirijo in Izraelom.',
        2: 'V tretjem letu pa se je pripetilo, da je Judov kralj Józafat prišel dol k Izraelovemu kralju.',
        3: 'Izraelov kralj je rekel svojim služabnikom: »Ali veste, da je Ramót v Gileádu naš, in mi bomo mirni in ga ne bomo vzeli iz roke sirskega kralja?«',
        4: 'Józafatu je rekel: »Hočeš z menoj iti v bitko k Ramót Gileádu?« Józafat je Izraelovemu kralju rekel: »Jaz sem, kakor si ti, moje ljudstvo kakor tvoje ljudstvo, moji konji kakor tvoji konji.«',
        5: 'Józafat je Izraelovemu kralju rekel: »Prosim te, danes poizvedi pri besedi od Gospoda.«',
        6: 'Potem je Izraelov kralj zbral skupaj preroke, okoli štiristo mož in jim rekel: »Ali naj grem zoper Ramót Gileád v bitko ali naj to opustim?« Rekli so: »Pojdi gor, kajti Gospod ga bo izročil v kraljevo roko.«',
        7: 'Józafat je rekel: » Ali tukaj ni več Gospodovega preroka, da bi lahko poizvedeli od njega?«',
        8: 'Izraelov kralj je rekel Józafatu: » Tukaj je še en mož, Jimlájev sin Miha, po katerem bi lahko poizvedeli od Gospoda. Toda sovražim ga, kajti glede mene ni dobro prerokoval, temveč zlo.« Józafat je rekel: »Naj kralj ne govori tako.«',
        9: 'Potem je Izraelov kralj poklical častnika in rekel: »Podvizaj sem Jimlájevega sina Miha.«',
        10: 'Izraelov kralj in Judov kralj Józafat sta sedela vsak na svojem prestolu, oblečena sta imela svoja svečana oblačila, na odprtem prostoru, pri vhodu velikih vrat Samarije in vsi preroki so prerokovali pred njima.',
        11: 'Cidkijá, Kenaanájev sin, si je naredil rogove iz železa in rekel: »Tako govori Gospod. ›S temi boš bodel Sirce, dokler jih ne boš použil.‹«',
        12: 'Vsi preroki so prerokovali tako, rekoč: »Pojdi gor k Ramót Gileádu in bodi uspešen, kajti Gospod ga bo izročil v kraljevo roko.«',
        13: 'Poslanec, ki je odšel, da pokliče Miha, mu je spregovoril, rekoč: »Glej torej, besede prerokov kralju soglasno razglašajo dobro. Naj bo tvoja beseda, prosim te, kakor beseda enega izmed njih in govori to, kar je dobro.«',
        14: 'Miha pa je rekel: » Kakor živi Gospod, kar mi Gospod reče, to bom govoril.«',
        15: 'Tako je prišel h kralju in kralj mu je rekel: »Miha ali naj gremo zoper Ramót Gileád, da se bojujemo ali naj opustimo?« Ta mu je odgovoril: »Pojdi in bodi uspešen, kajti Gospod ga bo izročil v kraljevo roko.«',
        16: 'Kralj pa mu je rekel: »Kolikokrat te bom zaklinjal, da mi ne poveš ničesar razen tega, kar je resnično v Gospodovem imenu?«',
        17: 'In ta je rekel: »Videl sem vsega Izraela razkropljenega na hribih kakor ovce, ki nimajo pastirja. Gospod je rekel: ›Ti nimajo gospodarja. Naj se v miru vrnejo, vsak mož k svoji hiši.‹«',
        18: 'Izraelov kralj je rekel Józafatu: »Ali ti nisem rekel, da glede mene ne bo prerokoval nobene dobre stvari, temveč zlo?«',
        19: 'Rekel je: »Poslušaj torej Gospodovo besedo: ›Videl sem Gospoda sedeti na njegovem prestolu in vso nebeško vojsko stati pri njem, na njegovi desnici in na njegovi levici.‹',
        20: 'Gospod je rekel: ›Kdo bo pregovoril Ahába, da bo lahko šel gor in padel pri Ramót Gileádu?‹ Nekdo je rekel na ta način, drugi pa na drug način.',
        21: 'Tam pa je prišel naprej duh in obstal pred Gospodom ter rekel: ›Jaz ga bom prepričal.‹',
        22: 'Gospod mu je rekel: ›S čim?‹ Rekel je: ›Šel bom naprej in bom lažniv duh v ustih vseh njegovih prerokov.‹ Rekel je: ›Ti ga boš prepričal in tudi prevladal. Pojdi naprej in stori tako.‹',
        23: 'Zdaj torej glej, Gospod je položil lažnivega duha v usta vseh teh tvojih prerokov in Gospod je glede tebe govoril zlo.«',
        24: 'Toda Kenaanájev sin Cidkijá je prišel bliže in Miha udaril po licu ter rekel: »Katero pot je Gospodov Duh odšel od mene, da govori tebi?«',
        25: 'Miha je rekel: »Glej, videl boš tisti dan, ko boš šel v najnotranjejšo sobo, da se skriješ.«',
        26: 'Izraelov kralj je rekel: »Vzemi Miha in ga odvedi nazaj k Amónu, voditelju mesta in h kraljevemu sinu Joášu',
        27: 'ter reci: ›Tako govori kralj: ›Postavita tegale v ječo in ga hranita s kruhom stiske in z vodo stiske, dokler ne pridem v miru.‹«',
        28: 'Miha je rekel: »Če se sploh vrneš v miru, Gospod ni govoril po meni.« In rekel je: »Prisluhni, oh ljudstvo, vsakdo izmed vas.«',
        29: 'Tako sta Izraelov kralj in Judov kralj Józafat odšla gor k Ramót Gileádu.',
        30: 'Izraelov kralj je rekel Józafatu: »Jaz se bom zamaskiral in vstopil v bitko, toda ti si nadeni svoja svečana oblačila.« Izraelov kralj se je zamaskiral in odšel v bitko.«',
        31: 'Toda sirski kralj je zapovedal svojim dvaintridesetim poveljnikom, ki so poveljevali nad njegovimi bojnimi vozovi, rekoč: »Ne borite se niti z majhnim niti z velikim, razen samo z Izraelovim kraljem.«',
        32: 'Pripetilo se je, ko so poveljniki bojnih vozov zagledali Józafata, da so rekli: »To je zagotovo Izraelov kralj.« Obrnili so se vstran, da se bojujejo zoper njega. Józafat pa je zavpil.',
        33: 'Pripetilo se je, ko so poveljniki bojnih vozov zaznali, da to ni bil Izraelov kralj, da so se obrnili od zasledovanja za njim.',
        34: 'Nek mož pa je preprosto napel lok in Izraelovega kralja zadel med člene prsnega oklepa. Zato je vozniku svojega bojnega voza rekel: »Obrni svojo roko in me odvedi ven iz bojišča, kajti ranjen sem.«',
        35: 'Bitka je ta dan narasla in kralj je ostal pokonci na svojem bojnem vozu zoper Sirce in zvečer umrl. Kri iz rane je tekla na sredo bojnega voza.',
        36: 'Okoli sončnega zahoda je po vsej vojski šel razglas, rekoč: »Vsak mož k svojemu mestu in vsak mož k svoji lastni deželi.«',
        37: 'Tako je kralj umrl in bil priveden v Samarijo in kralja so pokopali v Samariji.',
        38: 'V samarijskem ribniku je nekdo umival bojni voz in psi so lizali njegovo kri in umili so njegovo bojno opremo, glede na Gospodovo besedo, ki jo je govoril.',
        39: 'Torej preostala izmed Ahábovih dejanj in vse, kar je storil in slonokoščena hiša, ki jo je naredil in vsa mesta, ki jih je zgradil, mar niso zapisana v kroniški knjigi Izraelovih kraljev?',
        40: 'Tako je Aháb zaspal s svojimi očeti in namesto njega je zakraljeval njegov sin Ahazjá.',
        41: 'V četrtem letu Izraelovega kralja Ahába je nad Judom začel kraljevati Asájev sin Józafat.',
        42: 'Józafat je bil star petintrideset let, ko je začel kraljevati in v Jeruzalemu je kraljeval petindvajset let. Ime njegove matere je bilo Azúba, Šilhíjeva hči.',
        43: 'Hodil je po vseh poteh svojega očeta Asája. Ni se obrnil vstran od tega; delal je to, kar je bilo pravilno v Gospodovih očeh. Kljub temu visoki kraji niso bili odstranjeni, kajti ljudstvo je na visokih krajih še vedno darovalo in zažigalo kadilo.',
        44: 'Józafat je z Izraelovim kraljem sklenil mir.',
        45: 'Torej preostala izmed Józafatovih dejanj in njegova moč, ki jo je pokazal in kako se je bojeval, mar niso zapisana v kroniški knjigi Judovih kraljev?',
        46: 'Preostanek posvečenih vlačugarjev, ki so preostali v dneh njegovega očeta Asája, je izgnal iz dežele.',
        47: 'Potem ni bilo kralja v Edómu. Namestnik je bil kralj.',
        48: 'Józafat je naredil taršíške ladje, da gredo do Ofírja po zlato. Toda niso odšli, kajti ladje so se razbile pri Ecjón Geberju.',
        49: 'Potem je Ahábov sin Ahazjá Józafatu rekel: »Naj moji služabniki gredo s tvojimi služabniki na ladje.« Józafat pa ni hotel.',
        50: 'Józafat je zaspal s svojimi očeti in je bil pokopan s svojimi očeti v mestu svojega očeta Davida. Namesto njega je zakraljeval njegov sin Jehorám.',
        51: 'Ahábov sin Ahazjá je začel kraljevati nad Izraelom v Samariji v sedemnajstem letu Judovega kralja Józafata in nad Izraelom je kraljeval dve leti.',
        52: 'Počel je zlo v Gospodovih očeh in hodil po poti svojega očeta, po poti svoje matere in po poti Nebátovega sina Jerobeáma, ki je Izraela pripravil, da greši,',
        53: 'kajti služil je Báalu, ga oboževal in do jeze dražil Gospoda, Izraelovega Boga, glede na vse, kar je počel njegov oče.',
    },
}
